window.POEM_DB=window.POEM_DB||{};POEM_DB["song_022"]={"n":"方岳","dyn":"宋","poems":[{"t":"春晚 其一","f":"七言绝句","c":["一樽无计遣春留，落日伤情独倚楼。","柔绿拍堤如可染，老红满径为谁愁。"]},{"t":"丁祭","f":"七言绝句","c":["紫薇花下玉丁东，夜午牵牛亦未中。","孔壁尚馀金石奏，捲班翻过玉成宫。"]},{"t":"九日道中凄然忆潘邠老之句","f":"七言绝句","c":["满城风雨近重阳，城脚谁家菊自黄。","又是江南离别处，寒烟吹雁不成行。"]},{"t":"九日墨紫开","f":"七言绝句","c":["九日年年负物华，野香未肯到山家。","今年九日风光别，不独黄花更紫花。"]},{"t":"二月朔日食阴雨不见","f":"七言绝句","c":["飞飞细雨湿花朝，不省阳乌影动摇。","晚色漏晴山又紫，始知阴沴已潜消。"]},{"t":"入村 其一","f":"七言绝句","c":["十日春霖一日晴，打包作意办山行。","月明夜半雨声急，不道老天无十成。"]},{"t":"入村 其二","f":"七言绝句","c":["山深未必得春迟，处处山樱花压枝。","桃李不言随雨意，亦知终是有晴时。"]},{"t":"入村 其四","f":"七言绝句","c":["宿雨初晴晓日晶，弥川满谷白云平。","烂银堆里素螺髻，画出江潮万里横。"]},{"t":"入村 其三","f":"七言绝句","c":["闭门觅句每无悰，句在茅茨烟雨中。","和烟和雨收拾取，等晴却写与东风。"]},{"t":"入闽 其一","f":"七言绝句","c":["山云底事夜来雨，藏却奇峰不与看。","政说雨中看更好，划然捲起出晴峦。"]},{"t":"入闽 其二","f":"七言绝句","c":["雪龙怒吼出山去，二十里云行上天。","老去极知诗力退，只将日历记山川。"]},{"t":"又和晦翁棹歌 其一","f":"七言绝句","c":["烧药炉存草亦灵，煮茶灶冷水犹清。","老仙一去无消息，只有飞泉落佩声。"]},{"t":"又和晦翁棹歌 其七","f":"七言绝句","c":["又撑小艇过前湾，竹外庵居昼掩关。","桃李无言开未了，春风元自不曾閒。"]},{"t":"又和晦翁棹歌 其五","f":"七言绝句","c":["宿雨留云被半岩，晴光飘散雪毵毵。","沾衣不识骨轻重，下有老龙无底潭。"]},{"t":"又和晦翁棹歌 其二","f":"七言绝句","c":["桃花认得捕鱼船，醉著归来月满川。","山鬼已磨苍玉碧，要留名字与风烟。"]},{"t":"又和晦翁棹歌 其十","f":"七言绝句","c":["乘兴而来亦偶然，谁将阴壑作晴川。","笋舆更问星村路，去看溪南一线天。"]},{"t":"又和晦翁棹歌 其三","f":"七言绝句","c":["家在清溪第几峰，谁搴薜荔采芙蓉。","渔歌未断忽归去，翠壁一重云一重。"]},{"t":"又和晦翁棹歌 其六","f":"七言绝句","c":["竹绕寒栖藓径深，茎茎手种玉成林。","翠屏向晚无人对，犹识先生一寸心。"]},{"t":"又和晦翁棹歌 其八","f":"七言绝句","c":["云气藏山雪捲滩，地灵不与俗人看。","一篙略借秋崖便，九曲欲穷山雨寒。"]},{"t":"又和晦翁棹歌 其四","f":"词","c":["群仙曾此醉?船，插向苍厓不记年。","蕙帐夜寒闻鹤语，人民城郭自堪怜。"]},{"t":"又和晦翁棹歌 其九","f":"七言绝句","c":["莫说水穷山势开，匆匆急棹酒船回。","溪山欲尽兴无尽，撑入白云深处来。"]},{"t":"上巳游显亲寺题其壁 其四","f":"七言绝句","c":["属玉双飞水满塘，石炉柏子掩山房。","一瓶瀑煮春风湿，只听松声意自长。"]},{"t":"上巳游显亲寺题其壁 其二","f":"七言绝句","c":["松房小小雨留客，竹径深深鸟唤人。","烂醉不知三月暮，等閒又是一年春。"]},{"t":"上巳游显亲寺题其壁 其一","f":"七言绝句","c":["一犁初试茧栗犊，两岸对鸣晴雨鸠。","摇落碧桃花片片，石阑干下钓鱼舟。"]},{"t":"上巳游显亲寺题其壁 其三","f":"七言绝句","c":["芳草垂杨水底天，半晴半雨作春妍。","幅巾道服篷船坐，不是诗仙即酒仙。"]},{"t":"山居七咏 其三 中隐洞","f":"七言绝句","c":["终南少室苦跻攀，已入先生一笑间。","不学刘安便仙去，屋边尽自有佳山。"]},{"t":"山居七咏 其四 丹桂轩","f":"七言绝句","c":["何年进入玉华宫，香到君王紫禁枫。","月府归来衫袖冷，蟾蜍滴露洗秋红。"]},{"t":"山居七咏 其五 乳泉","f":"七言绝句","c":["正尔清寒与世殊，地灵不受柳诗愚。","昼长何似醒幽梦，碧玉壶深贮雪腴。"]},{"t":"山居七咏 其一 经史阁","f":"七言绝句","c":["买书堆屋当藏珍，砚水生春玉作麟。","此老大蒙稽古力，至今疏草墨花新。"]},{"t":"山居七咏 其二 省斋","f":"七言绝句","c":["圣处终难举似人，二三子在最情亲。","于中检点平生看，香缕萦帘眇此身。"]},{"t":"山居七咏 其七 湛然亭","f":"七言绝句","c":["一念惟馀睡作魔，鸥閒不与世同波。","迩来定力空诸妄，如以摩尼照浊河。"]},{"t":"山居七咏 其六 瑞萱堂","f":"七言绝句","c":["携得春归通德门，等閒万木亦沾恩。","母桃未熟蓬莱浅，连夜吹开堂北萱。"]},{"t":"山家 其一","f":"七言绝句","c":["午阴蒙密路萦纡，两两丽黄对引雏。","自可曲肱惊短梦，南山丛薄有于菟。"]},{"t":"山家 其二","f":"七言绝句","c":["明月相看未厌贫，好风无价一披襟。","苔檐不扫少来往，两部鸣蛙草自深。"]},{"t":"山桥月夜","f":"七言绝句","c":["寒声策策琅玕碧，香气浮浮菡萏红。","六月人间苦炎热，独搔残雪月明中。"]},{"t":"山樊 其二","f":"七言绝句","c":["竹屋寒无石鼎烟，春风吹作白龙涎。","平生奇处何关染，字以山樊亦自然。"]},{"t":"山樊 其一","f":"七言绝句","c":["只有江梅合是兄，水仙终似号夫人。","季方政尔难为弟，每恨诗评未逼真。"]},{"t":"中秋日社未五鼓祀社归月明如昼","f":"七言绝句","c":["月明如水带寒流，饮福灵坛晓未收。","不是社公唤我起，何缘一日两中秋。"]},{"t":"书元可扇","f":"七言绝句","c":["南薰殿上薰风老，雨便飞来占取凉。","书带香眠愁杳渺，云侵清簟竹方床。"]},{"t":"书手实簿","f":"七言绝句","c":["随缘常住薄于秋，不了钟鱼粥饭头。","叹息结绳人远矣，例教吾负剡藤羞。"]},{"t":"书客星阁 其一","f":"七言绝句","c":["平生看破刘文叔，不肯依乘赤伏符。","底处只缘曾识面，故应人唤作狂奴。"]},{"t":"书客星阁 其二","f":"七言绝句","c":["小留不过貂蝉耳，亦恐遭人白眼看。","已自费辞侯霸辈，归来漱石暮江寒。"]},{"t":"书维扬张君梅卷 其二","f":"七言绝句","c":["月明临得霜桥影，只恁横斜自一奇。","唤起江南归梦远，竹村烟水有茅茨。"]},{"t":"书维扬张君梅卷 其一","f":"七言绝句","c":["平生何逊扬州梦，到得扬州月自寒。","谁遣雪蓬春半树，诗情更作故人看。"]},{"t":"以嗜酒爱风竹卜居此林泉为韵作十小诗 其六","f":"五言绝句","c":["朝吾一笭箵，夕吾一觳觫。","诗肠其殷雷，此事底须卜。"]},{"t":"以嗜酒爱风竹卜居此林泉为韵作十小诗 其四","f":"五言绝句","c":["东坡真天人，落笔蓬莱宫。","何如赤壁笛，一鹤横秋风。"]},{"t":"元夕 其四","f":"七言绝句","c":["老去欢悰久已无，病来瘦骨不胜扶。","山居幸自依青士，身事何曾问紫姑。"]},{"t":"元夕 其一","f":"七言绝句","c":["团蒲曲几雪鬅鬙，寒入青灯澹似僧。","只有梅花一林月，酒杯诗笔已无能。"]},{"t":"元夕 其三","f":"七言绝句","c":["莫道山家不挂灯，脩身宝月一团冰。","清寒照见诸人胆，却问诸人见未曾。"]},{"t":"元夕 其二","f":"七言绝句","c":["去年人老已苍华，野蔌山醪办咄嗟。","到得今年人又老，也无筋力看梅花。"]},{"t":"元英先生家鸬鹚步当文正时其裔孙楷登进士赠之诗云唐家三百年冠盖谁有诗书到远孙予家自严徙徽而谱系远矣因览石刻次韵左方","f":"七言绝句","c":["唐人犹有故家存，山里鸬鹚步下村。","宗派傥容诗嗣续，横枝吾亦是儿孙。"]},{"t":"壬寅元日","f":"七言绝句","c":["一元坱圠先天易，万物胚浑太极图。","自嚼梅花冰片片，无人先后饮屠苏。"]},{"t":"少微山观橘","f":"七言绝句","c":["手斸苍烟竹径深，霜寒错落万黄金。","何年共话商山旧，分种归来欲满林。"]},{"t":"少微楼","f":"七言绝句","c":["不奈梅花尔许愁，天寒孤倚夕阳楼。","近城鸥鹭逢人惯，肯与渔蓑共钓舟。"]},{"t":"方红 其二","f":"七言绝句","c":["群仙南游三神山，亲留冰丹祛暑袢。","蕊珠侍宸辄分似，我其诗之累百番。"]},{"t":"月下 其二","f":"七言绝句","c":["春风不到莓苔石，山月自随烟水身。","穷是世间常事耳，不知颠倒几多人。"]},{"t":"月下 其一","f":"七言绝句","c":["月明正午一声雁，山静如秋两袖风。","鹤与苍头齐睡著，无人知我此山中。"]},{"t":"月中观梅","f":"七言绝句","c":["何物苍头不自量，踏梅踏月上山堂。","月明幸是无痕迹，可惜琼瑶一径香。"]},{"t":"月蚀","f":"七言绝句","c":["老兔酣眠一夜霜，妖蟆健啖未渠央。","人间今欠玉川子，生语聱牙满世香。"]},{"t":"风月堂夜饮","f":"七言绝句","c":["霜洗横枝月上初，春彝更可共谈无。","玉杯一一寒于雪，贮以诗肠渺似湖。"]},{"t":"东津","f":"七言绝句","c":["秋老江南隔岸山，断云衰草雨斑斑。","烟帆未可横江去，鸣橹恐妨鸥鹭閒。"]},{"t":"代赠","f":"七言绝句","c":["碧玉香深冷翠篝，梦魂不到玉搔头。","暮天欲雪寒如此，且问梅花愁不愁。"]},{"t":"山居十六咏 其七 小山","f":"五言绝句","c":["拳石以为山，勺水以为池。","我观于世间，何者非儿嬉。"]},{"t":"山居十六咏 其九 归来馆","f":"五言绝句","c":["归来遽云出，既出又归来。","自处苟如此，渊明安在哉。"]},{"t":"山居十六咏 其十四 饭牛庵","f":"五言绝句","c":["宁与厓下人，烟雨耕荦确。","读书亦何为，谨勿累吾角。"]},{"t":"山居十六咏 其二 幽谷","f":"五言绝句","c":["入林不厌深，避世不厌独。","倦飞鸟知还，毋惮下乔木。"]},{"t":"用吕宗卿山亭韵","f":"七言绝句","c":["约住山云倚断栏，云如秋薄与山环。","为山醉矣无山句，山不负予予负山。"]},{"t":"田头 其二","f":"七言绝句","c":["秧田多种八月白，草树初开九里香。","但得有牛横短笛，一蓑春雨自农桑。"]},{"t":"田头 其一","f":"七言绝句","c":["田头科斗古文字，石上臼洼山鼎彝。","勘破世间烦恼障，醉而已矣不吟诗。"]},{"t":"礼斗石","f":"七言绝句","c":["一方苍石老莓苔，只合渊明共酒杯。","岁晚出山成底事，至今笙鹤不归来。"]},{"t":"立春 其二","f":"七言绝句","c":["綵燕双簪翡翠翘，巧裁银胜试春韶。","东风已到阑干北，看见娇黄上柳条。"]},{"t":"立春 其一","f":"七言绝句","c":["冰丝玉缕簇青红，已逗花梢一信风。","梦到谢池新雪尽，暖烟含雨绿匆匆。"]},{"t":"立春 其三","f":"七言绝句","c":["池痕吹皱绿粼粼，才见池痕认得春。","香沁綵鞭旗脚转，自题兰帖记春新。"]},{"t":"立春日雷 其二","f":"七言绝句","c":["出地奔霆便发声，寒花衰草亦欣荣。","天公只要新群听，不等春来蛰已惊。"]},{"t":"立春日雷 其一","f":"七言绝句","c":["胜里春从午夜回，自挑生菜压春醅。","阿香不解人间事，便驾雷车送雨来。"]},{"t":"立春都堂受誓祭九宫坛 其一","f":"七言绝句","c":["欠伸残梦雪髼松，只等三茅午夜钟。","传钥省门星斗湿，不知春已转苍龙。"]},{"t":"立春都堂受誓祭九宫坛 其二","f":"七言绝句","c":["辇路香融雪未乾，鸡人初唱五更寒。","琼幡第一番花信，吹上东皇太乙坛。"]},{"t":"立春谢司法有诗次韵 其一","f":"七言绝句","c":["明日琼幡绕鬓飞，土牛才出草痕肥。","送寒正不关渠事，雪不来时未肯归。"]},{"t":"立春谢司法有诗次韵 其四","f":"七言绝句","c":["草亭亦欲识诗葩，连夜开将雪树花。","清处尽强陶学士，不关羔酒与龙茶。"]},{"t":"立春谢司法有诗次韵 其二","f":"七言绝句","c":["谁将健笔破天葩，清晓园林尽是花。","寒入崖云斋未久，诗肠虽吼尚禁茶。"]},{"t":"立春谢司法有诗次韵 其三","f":"七言绝句","c":["一夜挼云作雪飞，池塘已自绿生肥。","凭君检校阑干北，柳上新青归未归。"]},{"t":"立秋","f":"七言绝句","c":["秋日寻诗独自行，藕花香冷水风清。","一凉转觉诗难做，付与梧桐夜雨声。"]},{"t":"记画","f":"七言绝句","c":["閒云古木山藏寺，野渡孤舟水落矶。","秋色无人空黯淡，竹门未掩待僧归。"]},{"t":"买兰","f":"七言绝句","c":["几人曾识离骚面，说与兰花枉自开。","却是樵夫生鼻孔，担头带得入城来。"]},{"t":"光孝寺作茶供","f":"七言绝句","c":["一藤碎踏两山云，看尽朝岚与夕曛。","留得如来舍身相，共敲苍雪了炉熏。"]},{"t":"再用韵奉酬 其一","f":"七言绝句","c":["灞桥洗净冰霜面，拂略潮红笑向春。","莫作野桃看过了，烦诗说似武陵人。"]},{"t":"再用韵奉酬 其二","f":"七言绝句","c":["昔公安在见何晚，宁欲霜埋不受春。","不是三生曾一面，宁堪开向世间人。"]},{"t":"农谣 其三","f":"七言绝句","c":["小麦青青大麦黄，护田沙径绕羊肠。","秧畦岸岸水初饱，尘甑家家饭已香。"]},{"t":"农谣 其五","f":"七言绝句","c":["漠漠馀香著草花，森森柔绿长桑麻。","池塘水满蛙成市，门巷春深燕作家。"]},{"t":"农谣 其二","f":"七言绝句","c":["问舍求田计未成，一蓑锄月每含情。","春山树暖莺相觅，晓陇雨晴人独耕。"]},{"t":"农谣 其四","f":"七言绝句","c":["雨过一村桑柘烟，林梢日暮鸟声妍。","青裙老姥遥相语，今岁春寒蚕未眠。"]},{"t":"农谣 其一","f":"七言绝句","c":["春雨初晴水拍堤，村南村北鹁鸪啼。","含风宿麦青相接，刺水柔秧绿未齐。"]},{"t":"刘逊子架阁饷江茶 其二","f":"七言绝句","c":["醉眠彭泽几何日，只与吟诗办秫田。","灵草独醒山雨外，可曾持到漉巾前。"]},{"t":"刘逊子架阁饷江茶 其一","f":"七言绝句","c":["琵琶亭下春寒夜，湿尽青衫竟为谁。","江草江花恨何极，雪瓯如此却无诗。"]},{"t":"寻诗","f":"七言绝句","c":["蹇驴踏雪灞桥春，画出茅茨野水滨。","才见梅花诗便好，梅花却是定诗人。"]},{"t":"戏简王尉 其二","f":"七言绝句","c":["楚云迟上木兰船，惹得秋辞亦浪传。","不直翠眉亲唱与，故应无分学彭宣。"]},{"t":"戏简王尉 其一","f":"七言绝句","c":["半床明月老秋风，未必诗人一例穷。","比似乐天犹欠在，是非已落酒杯中。"]},{"t":"早春山中 其四","f":"七言绝句","c":["吟入梅花倚树腰，不知声撼雪飘飘。","山翁只道春无力，半日黏须未肯消。"]},{"t":"早春山中 其一","f":"七言绝句","c":["空濛山翠湿乌纱，逗密穿深一径斜。","谁画秋厓满头雪，石坛倚竹看梅花。"]},{"t":"早春山中 其五","f":"七言绝句","c":["同时乞得杏花栽，一样高低一处裁。","自是春风不齐整，半零落尽半胚胎。"]},{"t":"早春山中 其三","f":"七言绝句","c":["兰未曾芽柳未丝，是渠春早是春迟。","草塘寻见春风处，问讯如何自不知。"]},{"t":"早春山中 其二","f":"七言绝句","c":["竹边门自不须关，留与山云共往还。","芳草初齐梅点点，绿丝茸地鹿胎斑。"]},{"t":"有叹","f":"七言绝句","c":["月如此好吴牛喘，雪不胜寒蜀犬狺。","莫怪叔孙并禄父，不知周孔是何人。"]},{"t":"有客","f":"七言绝句","c":["晚径云深雨未乾，爱闲有客过方干。","茶瓯之外无祗待，清坐不言松韵寒。"]},{"t":"次韵双头牡丹","f":"七言绝句","c":["春入多情草木妖，霓裳相倚奏咸韶。","玉栏一样红如洗，不比觚棱锁二乔。"]},{"t":"次韵方教采芹亭 其二","f":"七言绝句","c":["亭与樵岚一样新，诗书不受世间尘。","清风明月来无尽，不在溪山只在人。"]},{"t":"次韵方教采芹亭 其九","f":"七言绝句","c":["山是乌山落一支，径烦诗眼相亭基。","舞雩人在春风里，清坐不言山更奇。"]},{"t":"次韵方教采芹亭 其三","f":"七言绝句","c":["竹外清溪溪外峰，谁搴薜荔采芙蓉。","所思渺渺隔何许，我欲从之骑九龙。"]},{"t":"次韵方教采芹亭 其六","f":"七言绝句","c":["客怀老去向谁开，白雪茎茎不用栽。","只有爱书馀习在，待携残藁过溪来。"]},{"t":"次韵方教采芹亭 其五","f":"七言绝句","c":["莫问秋风八月槎，一蓑欲老水之涯。","笔床茶灶肯同住，毕竟吾宗是作家。"]},{"t":"次韵方教采芹亭 其四","f":"七言绝句","c":["终日看山自一奇，寒溪更与月相宜。","采芹人去夜岑寂，政是先生得意时。"]},{"t":"次韵方教采芹亭 其八","f":"七言绝句","c":["山自西来玉作层，千峰住处一溪萦。","宜晴宜雨乍明灭，不是老天无十成。"]},{"t":"次韵方教采芹亭 其一","f":"七言绝句","c":["手斸风烟不占多，春来物物是阳和。","极知山与诗为地，老去无诗奈若何。"]},{"t":"次韵方教采芹亭 其十","f":"七言绝句","c":["研朱滴露月三更，见说群书作堵环。","君自苦于经传癖，不如借我去看山。"]},{"t":"次韵方教采芹亭 其七","f":"七言绝句","c":["默坐焚香尽自佳，莫随俗眼乱空花。","古今人物不相及，元只中间隔一些。"]},{"t":"次韵方蒙仲高人亭 其九","f":"五言绝句","c":["相从文字盟，不与如此酒。","他日有移文，毋令猿鹤受。"]},{"t":"次韵叶宗丞湘梅 其一","f":"七言绝句","c":["双娥洒泣凝春竹，粉落脂残不忍妆。","开作疏花寄幽独，雪中仍作楚骚香。"]},{"t":"次韵叶宗丞湘梅 其二","f":"七言绝句","c":["庾岭以南非楚产，离骚不载亦堪嗟。","行吟傥见灵均否，且与辛夷定等差。"]},{"t":"次韵牟监簿 其一","f":"七言绝句","c":["几携笔砚傍书林，吟到更寒月未沈。","有客忽从天禄至，人间便隔五云深。"]},{"t":"次韵牟监簿 其二","f":"七言绝句","c":["秋声满院有谁来，亦欲从君话老怀。","隔竹已敲茶臼雪，不知何日又清斋。"]},{"t":"次韵至能湖上","f":"七言绝句","c":["春山如染费人诗，骤马新堤拂柳丝。","杜宇一声春欲暮，海棠睡去未曾知。"]},{"t":"次韵别友","f":"七言绝句","c":["长汀草色恨连天，一片飞红涨绿川。","寒入湘帘君又去，只随燕子过年年。"]},{"t":"次韵别友","f":"七言绝句","c":["砚香不肯与山留，雨浥寒花断送秋。","后夜酒醒诗更好，淡烟荒草并渔舟。"]},{"t":"次韵君用寄茶","f":"七言绝句","c":["茅舍生苔费梦思，竹炉烹雪复何时。","北山怕有移文在，谨勿便令猿鹤知。"]},{"t":"次韵宋尚书山居十五咏 其十一 木瓜坞","f":"七言绝句","c":["与山作计未为疏，尽有奇功可屡书。","但得相寻双脚健，不须论报计琼璩。"]},{"t":"次韵宋尚书山居十五咏 其十五 东斋","f":"七言绝句","c":["佳木扶疏漏晓暾，书床留得夜来云。","幽经谈尽无功课，自理东窗芝朮熏。"]},{"t":"次韵宋尚书山居十五咏 其十三 正己亭","f":"七言绝句","c":["少日横刀属两鞬，玉花曾几试戎鞯。","归来聊复观仁耳，不在惊鸿落劲弦。"]},{"t":"次韵宋尚书山居十五咏 其三 竹径","f":"七言绝句","c":["此君老去更风猷，冰雪生寒我辈流。","穿径略容携客共，交情畴昔雅相投。"]},{"t":"次韵宋尚书山居十五咏 其六 烂柯台","f":"七言绝句","c":["玉行敲断欲生尘，翻手那知局面新。","到了不妨饶一著，旁观自有识机人。"]},{"t":"次韵宋尚书山居十五咏 其九 卧云庵","f":"七言绝句","c":["半坞云侵藓石床，向来忧乐已俱忘。","墙西有竹曾留鹤，梦亦相携入帝乡。"]},{"t":"次韵宋尚书山居十五咏 其二 金沙荼蘼径","f":"七言绝句","c":["露浥晴光对洗妆，柔条无力不成行。","阿环淡伫阿娇丽，一种风流各自香。"]},{"t":"次韵宋尚书山居十五咏 其七 茶岩","f":"七言绝句","c":["壑底云香不等雷，便携石鼎与俱来。","鹁鸠唤得西溪雨，顿得春从齿颊回。"]},{"t":"次韵宋尚书山居十五咏 其五 海棠径","f":"七言绝句","c":["酒泻银壶莫近傍，怕惊花睡损残妆。","拟题报答春风句，也恐春风未敢当。"]},{"t":"次韵宋尚书山居十五咏 其十 梅坡","f":"七言绝句","c":["风雪灞桥篱落间，寒驴乘兴寄曾攀。","三生习气除难尽，也许渠分一半山。"]},{"t":"次韵宋尚书山居十五咏 其四 清音亭","f":"七言绝句","c":["净洗从前两耳埃，溪声并逐雨声来。","此奇赖有诗能领，一笑钟期安在哉。"]},{"t":"次韵宋尚书山居十五咏 其十四 紫阳阁","f":"七言绝句","c":["隔岸烟云一望间，夜深笙鹤与俱还。","不缘曾识谪仙面，未必烟云住此山。"]},{"t":"次韵宋尚书山居 ?然堂","f":"词","c":["心亦元如止水渊，断无尘想到诸贤。","左蜗不断追?梦，说与青山恐未然。"]},{"t":"次韵宋尚书山居 日涉园","f":"七言绝句","c":["老石山苔手自治，爱閒诗最与山宜。","园官莫惜频来往，破费春风又几时。"]},{"t":"次韵宋尚书山居 见南山亭","f":"七言绝句","c":["能令诗腹化神奇，香到黄花秋力微。","我醉悠然山亦醉，竹深啼鸟自忘机。"]},{"t":"次韵宋尚书山居 亦乐堂","f":"七言绝句","c":["分得山云老一瓢，梦寒不记紫宸朝。","无人画出閒中味，吟入梅花雪径遥。"]},{"t":"次韵宋尚书山居 息斋","f":"七言绝句","c":["尘途长逐众人忙，不抵斋扉一枕凉。","世路巇岖吾倦至，底须辛苦为膏粱。"]},{"t":"次韵宋尚书山居 虚静堂","f":"七言绝句","c":["世事鸥忘句肯卑，云深料理旧花枝。","了无一鸟传幽意，只对青山自解颐。"]},{"t":"次韵宋尚书山居 赋梅堂","f":"七言绝句","c":["夜草春笺奏玉皇，横波曾识水曹郎。","砚香留得东风在，一吐嵬崔冰雪肠。"]},{"t":"次韵宋尚书山居 醉陶轩","f":"七言绝句","c":["时复中之兴已高，是非一付与春醪。","向来醉眼略四海，粗记柴桑人姓陶。"]},{"t":"次韵李山窗","f":"七言绝句","c":["一船明月秋江冷，曾与梅花有约来。","谁唤雪溪回短棹，宁孤何逊莫孤梅。"]},{"t":"次韵杜监簿 其二","f":"七言绝句","c":["杜曲无边风露秋，瓮头酒熟了无忧。","一诗连夜穿兵卫，略似齐城战火牛。"]},{"t":"次韵杜监簿 其三","f":"七言绝句","c":["赢得萧萧两鬓秋，山城斗大转多忧。","人间纵有万钱鹤，身外何如十具牛。"]},{"t":"次韵杜监簿 其四","f":"七言绝句","c":["不须把浅不防秋，底事山樵亦过忧。","说与诸公那解此，但知两角战蜗牛。"]},{"t":"次韵杜监簿 其一","f":"七言绝句","c":["风雨重阳又一秋，白衣人至复何忧。","东篱只此黄花是，未必渊明风马牛。"]},{"t":"次韵牡丹 其二","f":"七言绝句","c":["娇红深倚翠云团，髣髴三生吴綵鸾。","诗眼顿惊春富贵，雨侵衫袖不知寒。"]},{"t":"次韵牡丹 其一","f":"七言绝句","c":["银壶贮雪褪轻红，费尽思量句不工。","若使春风但桃李，春风殊未可雌雄。"]},{"t":"次韵陈帐管秋思 其二","f":"七言绝句","c":["人家一样捲湘帘，惹起新愁到酒边。","久客不知诗瘦损，小楼孤倚月娟娟。"]},{"t":"次韵陈帐管秋思 其一","f":"七言绝句","c":["秋风吹裂旧荷衣，自读离骚倚落晖。","已觉芦花洲渚冷，水天归雁著行飞。"]},{"t":"次韵陈侍郎谢送牡丹 其二","f":"七言绝句","c":["手斸苍苔玉一栏，山家初见眼犹寒。","移根莫厌凡红紫，只做春风一样看。"]},{"t":"次韵陈侍郎谢送牡丹 其一","f":"七言绝句","c":["人在金华殿角头，诗情却遣为花留。","春风不入癯仙眼，六六峰寒隔几州。"]},{"t":"次韵郑省仓 其二","f":"楚辞体","c":["归去来兮月一船，世途难似上青天。","烟蓑自与轻鸥狎，却在风涛阿那边。"]},{"t":"次韵郑省仓 其一","f":"词","c":["买鱼聊复醉?船，万事从来付老天。","欲办把茅无计可，不量吾力更筹边。"]},{"t":"次韵客饟鲈蟹","f":"七言绝句","c":["江鲈淮蟹不论钱，肯到湖边明月船。","玉鲙雪螯新煮酒，桂花香后菊花前。"]},{"t":"次韵赵佥为赵宰画野水多于地春山半是云盖宰之尊公诗也","f":"七言绝句","c":["竹屋无人肯见过，寒云自傍钓船多。","老仙更在云深处，奈此春山野水何。"]},{"t":"次韵赵尉","f":"七言绝句","c":["世于吾道转崎岖，是与非耶一子虚。","借得祁山两间屋，一间分与月明居。"]},{"t":"次韵赵尉梅句 其一","f":"七言绝句","c":["冰雪之晨草木屯，南枝亦有未招魂。","一愁泥就孤山骨，正恐诗谈太不根。"]},{"t":"次韵赵尉梅句 其二","f":"七言绝句","c":["疏花不受世间寒，得圣之清自可餐。","今日湖山人已朽，何如茅屋雪中看。"]},{"t":"次韵赵端明万花园 其四","f":"七言绝句","c":["玉箫吹断知何许，柳径日长娇燕舞。","鹤城半掩人未归，数点春愁杏花雨。"]},{"t":"次韵赵端明万花园 其二","f":"七言绝句","c":["和气能消塞上寒，却于边事颇相干。","酒旗歌鼓秋千外，新绿柔红又几般。"]},{"t":"次韵赵端明万花园 其三","f":"七言绝句","c":["风逗湘帘雪絮飞，池痕雨过曲尘肥。","扬州十里春犹在，细柳营深解铁衣。"]},{"t":"次韵赵端明万花园 其一","f":"七言绝句","c":["万花锦绣同民乐，不比青山独乐园。","办得春风共花醉，尽教蝶闹与蜂喧。"]},{"t":"次韵徐宰集珠溪","f":"七言绝句","c":["瀑煮春风生意长，梅花吹雪入诗香。","夜寒记得僧房梦，脩竹半窗云一床。"]},{"t":"次韵斋宿 其一","f":"七言绝句","c":["可是诗边欠老干，藓床相对话灯残。","秋城一夜江湖晚，风雨重阳菊自寒。"]},{"t":"次韵斋宿 其二","f":"七言绝句","c":["黄花白发两关情，并入斋房长短更。","久客自知秋意思，底须蛩雨做寒声。"]},{"t":"次韵梁倅","f":"七言绝句","c":["把住新花做好看，伤春时共倚阑干。","醉中不记暮烟碧，杨柳楼深燕子寒。"]},{"t":"次韵梁倅秋日白牡丹","f":"七言绝句","c":["自掩窗纱护夕阳，碧壶深贮溜晴光。","可曾见此春风面，净洗铅华试晓霜。"]},{"t":"次韵清脩老墨梅新茗","f":"七言绝句","c":["此诗合让简斋老，尽洗世间声色尘。","我更凿空难著语，蹇驴粗记雪桥春。"]},{"t":"次韵菖蒲","f":"七言绝句","c":["瓦盆犹带涧声寒，亦有诗情几砚间。","抱石小龙鳞甲老，夜窗云气故斑斑。"]},{"t":"次韵程兄投赠 其一","f":"七言绝句","c":["北里南邻尽往还，那知有客住云间。","相过肯作乡人面，问讯春溪两岸山。"]},{"t":"次韵程兄投赠 其二","f":"七言绝句","c":["知无燕颔可封侯，索米长安亦强留。","输与鲈肥菰叶滑，吴中风味老孤舟。"]},{"t":"次韵程弟 其十","f":"七言绝句","c":["此腹宁须文字香，漫淹齑瓮半青黄。","午窗一枕齁齁睡，世上何人最得忙。"]},{"t":"次韵程弟 其九","f":"七言绝句","c":["鱼鸟相忘不世情，浮生于我一丝轻。","夜凉月色光如水，莫遣微云滓太清。"]},{"t":"次韵程弟 其一","f":"七言绝句","c":["一船月自不嫌贫，伴我荒湾理钓缗。","归去莫横深夜笛，怕惊溪友与山宾。"]},{"t":"次韵程弟 其二","f":"七言绝句","c":["三径风烟手自开，春猿秋鹤几徘徊。","松根石铫烹鱼眼，老子行山又一回。"]},{"t":"次韵程弟 其四","f":"七言绝句","c":["眼中转觉可人稀，得似孤云自在飞。","花落花开俱有意，略于閒处见几微。"]},{"t":"次韵程弟 其三","f":"七言绝句","c":["槿援茅茨隐者家，底须日历记年华。","山花山草无终极，秋后寂寥春自葩。"]},{"t":"次韵程弟 其五","f":"七言绝句","c":["草堂四壁一瓢空，举世无人与我同。","黄犊山南又山北，犁春犹有古人风。"]},{"t":"次韵程弟 其七","f":"七言绝句","c":["垒曲成台糟筑丘，衰迟无复少年游。","君看烟草离离外，不问人间第一流。"]},{"t":"次韵程弟 其八","f":"七言绝句","c":["莫为盘飧烹不鸣，借公松石听溪声。","貂蝉只是麒麟楦，寄语诸公卿自卿。"]},{"t":"次韵程弟 其六","f":"七言绝句","c":["柴门虽设不曾开，俗面向人三寸埃。","却是前溪双白鹭，门关不住又飞来。"]},{"t":"次韵谢兄立春戏拟春帖子 其三","f":"七言绝句","c":["天地春回万寿杯，宫云留雪玉崔嵬。","晓供帖子琼幡重，携得韶风下殿来。"]},{"t":"次韵谢兄立春戏拟春帖子 其二","f":"七言绝句","c":["天家观阙玉重重，逼入春皇一信风。","生意无边青欲动，微茫淡霭暖烟中。"]},{"t":"次韵谢兄立春戏拟春帖子 其一","f":"七言绝句","c":["泉脉晴融太液池，内人初晓玉参差。","东风认得农祥正，吹作丰年御制诗。"]},{"t":"次韵谢兄立春戏拟春帖子 其四","f":"七言绝句","c":["天与君王共一仁，只将仁与物为春。","要令率土无枯槁，未赏冰池皱玉粼。"]},{"t":"次韵谢兄立春戏拟春帖子 其五","f":"七言绝句","c":["青旗簇仗赐银幡，共以升平奉至尊。","阊阖千官花底散，紫泥香熟诏书温。"]},{"t":"次韵酬因胜老 其二","f":"七言绝句","c":["雁落平沙字字愁，打包不肯与山留。","一篷烟雨载秋去，诗在江南芦荻洲。"]},{"t":"次韵酬因胜老 其一","f":"七言绝句","c":["误脱农蓑拾汉科，空山奈此月明何。","秋风又跨扬州鹤，行路正难愁思多。"]},{"t":"次韵酬因胜老 其三","f":"七言绝句","c":["浅山如霁水连天，江北江南路几千。","入梦老亲双白发，归欤早及菊花前。"]},{"t":"次韵酬奚兄 其二","f":"七言绝句","c":["但得梅花过一冬，那须圣酒送文穷。","扬州不见梅花面，莫是何郎句未工。"]},{"t":"次韵酬清脩老","f":"七言绝句","c":["玉堂老作清脩记，曾许渠为我辈人。","髣髴三生虎溪笑，偶然一见面如春。"]},{"t":"次韵酬率翁 其二","f":"七言绝句","c":["但得清溪裹草堂，溪头山色有炎凉。","秋崖一出四年矣，想见松花满石床。"]},{"t":"次韵酬率翁 其一","f":"七言绝句","c":["戍楼梦不到中州，杜牧新愁亦倦游。","留得荷锄双手在，山寒芋栗要人收。"]},{"t":"此君室 其一","f":"五言绝句","c":["匪书谁与稽，匪竹谁与居。","以书造竹所，俯仰千载馀。"]},{"t":"约鲁山兄","f":"七言绝句","c":["莫说寻芳已后时，春蔬解甲茗搴旗。","松风石铫晴云盌，不是吾曹未必奇。"]},{"t":"自嘲","f":"七言绝句","c":["耕雨虽微负郭田，卧云不用买山钱。","春蓑健犊宁无语，又写前衔见集贤。"]},{"t":"至日","f":"七言绝句","c":["至日观书不几行，梅梢横影月昏黄。","汉家红影无人见，未必曾添一线长。"]},{"t":"行田 其二","f":"七言绝句","c":["老农具榻茅茨底，准拟先生欲岸巾。","笑道已呼儿贳酒，月明且不厌家贫。"]},{"t":"行田 其一","f":"七言绝句","c":["屋头乌桕午阴密，牛与牧童相对眠。","不是官中催税急，十年前已学耕田。"]},{"t":"观山","f":"七言绝句","c":["一层云放一层山，小市人家翠欲环。","检点只疑低数尺，一层山向隐云间。"]},{"t":"观刈 其一","f":"七言绝句","c":["石田荦确底须嫌，苦说频年不下镰。","烟雨一犁经老手，翻匙香雪十分甜。"]},{"t":"观刈 其二","f":"七言绝句","c":["蹄豚盂酒祝瓯窭，一饱人间百事休。","已约山妻同野饭，今年又胜去年秋。"]},{"t":"观刈 其三","f":"七言绝句","c":["秋来谁不负归田，炊玉尝新喜欲颠。","乞我一年横短笛，太平有象是丰年。"]},{"t":"观天井","f":"七言绝句","c":["雷斧何年翠凿成，老龙吟苦雪涛惊。","霜晴未用为霖在，留与春蓑作太平。"]},{"t":"观池中鸂鶒逐其自外来者","f":"七言绝句","c":["久住成家不见猜，傍船水暖逐毰毸。","岸沙能占春多少，长恐诸侯客子来。"]},{"t":"观荷 其一","f":"七言绝句","c":["南薰独擅水云乡，不许人间别有香。","是草是花开一遍，春风却似欠商量。"]},{"t":"观荷 其二","f":"七言绝句","c":["春红树树或丛丛，一一托根尘土中。","不道独清冰氏子，炎天玉立水晶宫。"]},{"t":"观荷 其四","f":"七言绝句","c":["莲有濂溪梅有逋，两家言句满江湖。","自怜尚与梅花隔，曾识先生太极图。"]},{"t":"观荷 其五","f":"七言绝句","c":["花叶根茎迥不同，略无些子犯春风。","羽衣纵落寻芳后，解作清凉烈日中。"]},{"t":"观梅 其二","f":"七言绝句","c":["卧疴半月不曾来，等得来时渐次开。","世外交情无久近，岁寒然后始知梅。"]},{"t":"观梅 其三","f":"七言绝句","c":["几日商量雪不成，竹边寒得瘦棱层。","秋崖老子缩如猬，撚断吟髭寸寸冰。"]},{"t":"观梅 其四","f":"七言绝句","c":["片片随风隔坞飘，野香相逐过溪桥。","今年便觉春风早，雪不成绵到地消。"]},{"t":"观梅 其五","f":"七言绝句","c":["较似年时劣不如，花头小小两疏疏。","但令半点微酸在，憔悴空山尽有馀。"]},{"t":"观梅 其六","f":"七言绝句","c":["老树槎枒只一花，气条亦不放横斜。","无风无雨无烟月，独立人间莫怨嗟。"]},{"t":"访恭率翁不值","f":"七言绝句","c":["且容晴梦泊鸥沙，传语茶头莫点茶。","山客不归秋自老，满城风雨又黄花。"]},{"t":"过楚道人舍 其一","f":"七言绝句","c":["纷纷俗子俗到骨，对面有山那得看。","不料楚髯能辨此，夜深月冷石阑干。"]},{"t":"过楚道人舍 其二","f":"七言绝句","c":["平生诗友刘宾客，醉墨曾传到雪庐。","煞说竹溪茅屋好，便能诗亦不如渠。"]},{"t":"过缙云胡君作茶古松下丛兰中","f":"七言绝句","c":["十丈苍皮带雪僵，山云归晚泊书床。","不缘曾读离骚熟，兰亦欺人未肯香。"]},{"t":"严陵待锁 其一","f":"七言绝句","c":["一舸秋风梦亦寒，津人只作贾胡看。","断桥袖手暮烟合，等得芦花雪满滩。"]},{"t":"别子才司令","f":"七言绝句","c":["不如意事常八九，可与语人无二三。","自识荆门子才甫，梦驰铁马战城南。"]},{"t":"别汤卿不值","f":"七言绝句","c":["云深只以竹为墙，新雨才乾径草长。","野鹤已随溪客远，一方玄玉带诗香。"]},{"t":"即事","f":"七言绝句","c":["自刈香粳税水舂，旋篘新酒搦泥封。","晚菘种已无馀地，不枉归田学老农。"]},{"t":"即事 其二","f":"七言绝句","c":["荒烟疏树野人家，竹外寻诗一径斜。","山鸟亦知人意思，忽翻残雪啄梅花。"]},{"t":"即事 其一","f":"七言绝句","c":["野径孤横雪外枝，岁寒了不受春知。","世间所谓奇男子，除却梅花更是谁。"]},{"t":"即事十首 其十","f":"七言绝句","c":["残鬓萧萧不满梳，秋风椎髻立庭除。","日明照见崚嶒影，自是山僧不是予。"]},{"t":"即事十首 其九","f":"七言绝句","c":["得摇牙处尽摇牙，底用鸣声绕鬓哗。","政自为渠眠不熟，西风吹叶打窗纱。"]},{"t":"即事十首 其八","f":"七言绝句","c":["赤日黄埃槁欲焚，赛神迎佛正纷纷。","天公老手何关汝，一雨晴无一点云。"]},{"t":"即事十首 其七","f":"七言绝句","c":["岩暝林霏日夕佳，百年宁复此秋崖。","不须更问青乌子，一锸相随死便埋。"]},{"t":"即事十首 其六","f":"七言绝句","c":["记得秋风此削瓜，偶遗子亦自成花。","生生造化无终极，但有根芽未可涯。"]},{"t":"即事十首 其五","f":"七言绝句","c":["龙骨翻翻水倒流，藕花借与稻花秋。","鱼兼熊掌不可得，宁负风光救口休。"]},{"t":"即事十首 其四","f":"七言绝句","c":["藤蔓穿篱碍草扉，与僮扶起绕松围。","髯龙鳞甲动云雨，缚著空山莫遣飞。"]},{"t":"即事十首 其三","f":"七言绝句","c":["畦丁亸懒欲谁欺，趁我山行始一犁。","只有山花山鸟笑，主人元自不曾知。"]},{"t":"即事十首 其二","f":"七言绝句","c":["野塘尺水亦生烟，宁有馀波可及田。","商略且为鱼作计，须臾毋死待丰年。"]},{"t":"即事十首 其一","f":"七言绝句","c":["窥园何物愠无端，疥手偷将玉雪团。","不道主林神忌讳，鸟乌声乐并催残。"]},{"t":"君用致红梅云不开数年矣","f":"七言绝句","c":["山家已作枯槎看，带雪移来却自春。","一夜揣摩花意思，宁将醉面向村人。"]},{"t":"李监饟四物各以一绝答之 土瓜","f":"七言绝句","c":["蹲鸱不紫茯苓黄，初斸春烟带土香。","久觉相如诗肺渴，入山餐玉不传方。"]},{"t":"李监饟四物各以一绝答之 鹅鲊","f":"七言绝句","c":["翠箬红泥曲米春，篆滩风月入厨珍。","谁令渠识黄庭字，且醉胸中无字人。"]},{"t":"李监饟四物各以一绝答之 鲟鲊","f":"七言绝句","c":["肉未为奇骨最奇，透明玛瑙碎琉璃。","老饕不奈残牙齿，却爱桃花软玉脂。"]},{"t":"汪圣权自开寿域作小亭其前植桂环之谒予作扁有诗云不分桂籍一毫月枉踏槐花十八秋其志亦可悲也已为题曰桂穴而系之诗 其一","f":"七言绝句","c":["老蚕作茧自缠裹，不肯生前只么休。","却后百年牢记取，满身明月桂花秋。"]},{"t":"汪圣权自开寿域作小亭其前植桂环之谒予作扁有诗云不分桂籍一毫月枉踏槐花十八秋其志亦可悲也已为题曰桂穴而系之诗 其二","f":"七言绝句","c":["白头不了秋风债，桂穴锄云种一枝。","与世今迷日五色，莫教地下有人知。"]},{"t":"汪运干饷酒 其一","f":"七言绝句","c":["长须手挈一壶酒，问识浣花工部无。","蓑笠荷锄烟雨外，再三不信是耕夫。"]},{"t":"汪运干饷酒 其二","f":"七言绝句","c":["酒吾甚爱径须醉，快洗平生老瓦盆。","中有笔峰能画我，一牛横笛过孤村。"]},{"t":"牡丹多不开花","f":"七言绝句","c":["韶风万物照我庐，昨岁骈头今并疏。","自是爱花心不足，何知物物有乘除。"]},{"t":"牡丹多不开花","f":"七言绝句","c":["少作花头多作丛，十分能有几分红。","春工自不容人力，抱瓮穷年笑此翁。"]},{"t":"社日","f":"七言绝句","c":["燕子今年掯社来，翠瓶犹有去年梅。","丁宁莫管杏花俗，付与春风一道开。"]},{"t":"社日益明叔见过","f":"七言绝句","c":["溪云酝酿社公雨，肯踏寒莎过阿戎。","亦有小诗拈未出，且携瀑布煮春风。"]},{"t":"芭蕉","f":"七言绝句","c":["数叶芭蕉数叶秋，灯长雨久不眠愁。","灵溪寺里夜曾听，又听灵溪溪水流。"]},{"t":"芭蕉","f":"七言绝句","c":["自是愁人愁不消，非干雨里听芭蕉。","芭蕉易去愁难去，移向梧桐转寂寥。"]},{"t":"还留石亭","f":"七言绝句","c":["枯荷折苇卧凫鸥，小雨轻烟画出秋。","自唤短篷将老砚，石亭寻客了诗愁。"]},{"t":"閒居无与酬答因假庭下三物作 竹答梅","f":"七言绝句","c":["不随桃李共争春，犹作疏花向世人。","耸壑未妨吾独步，要看晚节玉璘珣。"]},{"t":"閒居无与酬答因假庭下三物作 桃讽梅","f":"七言绝句","c":["不肯春风时世妆，岁寒崖谷倚冰霜。","人间亦有知香者，盍遣一枝横出墙。"]},{"t":"閒居无与酬答因假庭下三物作 梅问竹","f":"七言绝句","c":["一壑烟寒孰与娱，横斜影对此君臞。","风饕雪虐转强项，惟我与君其是夫。"]},{"t":"閒居无与酬答因假庭下三物作 梅谢桃","f":"七言绝句","c":["下欲成蹊春已残，雨红犹自有人看。","极知不与君同调，但守平生一点酸。"]},{"t":"陈汤卿致绍梅","f":"七言绝句","c":["林下风流自一家，纵施朱亦不奢华。","冷香犹带灞桥雪，不比春风桃杏花。"]},{"t":"饮荼蘼花下招蔡公庆","f":"七言绝句","c":["春工管不了霓裳，风自南来占取香。","一夜谢池晴雪满，无人说与蔡中郎。"]},{"t":"龟巢夜宴","f":"七言绝句","c":["落日鸳鸯睡浅坡，荷花初醒水微波。","玉箫吹断晴云湿，最觉池宽得月多。"]},{"t":"净明斋","f":"七言绝句","c":["山径留云雨未乾，松声长共涧声寒。","青鞋莫踏苍苔破，借与秋厓半日看。"]},{"t":"卖花翁","f":"七言绝句","c":["不论袍紫与鞓红，一朵千金费化工。","人共醉花花亦醉，莫教山圃不春风。"]},{"t":"受诰口号 其一","f":"七言绝句","c":["归我南山老不遭，孟亭几梦赭黄袍。","强渠枉费平生力，不直君王一字褒。"]},{"t":"受诰口号 其二","f":"七言绝句","c":["雪寒月瘦鬓成丝，缘底天家圣得知。","从此江山尽驱使，小民奉敕遣吟诗。"]},{"t":"夜大风","f":"七言绝句","c":["一夜东风太放颠，草塘打破钓鱼船。","赖渠自任脩船费，无数乱堆榆荚钱。"]},{"t":"夜雨屋漏","f":"七言绝句","c":["莫怨乖龙横见治，满床诗卷尽淋漓。","人间书疏何为者，径挽天河一洗之。"]},{"t":"岩桂花","f":"七言绝句","c":["谁遣秋风开此花，天香来自玉皇家。","郁金裳浥蔷薇露，知是仙人萼绿华。"]},{"t":"明日诗至过相称谓次韵还之","f":"七言绝句","c":["捲还一幅玉壶秋，无实之名我所忧。","不似蒙庄解齐物，以吾为马以为牛。"]},{"t":"林和靖墓","f":"七言绝句","c":["结庐旧与青山对，脩竹萧疏半不存。","惟有亭前古梅在，暗香疏影几黄昏。"]},{"t":"苦雨 其一","f":"七言绝句","c":["稼欲登场只等晴，入仓方始是收成。","雨须小住为佳耳，已约邻翁话太平。"]},{"t":"苦雨 其二","f":"七言绝句","c":["翁自无田望有秋，有秋翁自饱齁齁。","此愁不遣吾人管，欲遣何人管此愁。"]},{"t":"茉莉","f":"七言绝句","c":["闽雨揉香摘未稀，钩帘顿觉暑风微。","只应雪外梅花笑，肯与儿曹入枕帏。"]},{"t":"郑文振席上","f":"七言绝句","c":["香篆烧残小玉虬，荷花深处浴凫鸥。","谈诗未了催行酒，忽送清歌浅黛愁。"]},{"t":"采筇","f":"七言绝句","c":["此君有节瘦如许，老子无心酷似之。","莫向人间危处去，溪云径雪尽扶持。"]},{"t":"钓台","f":"七言绝句","c":["羊裘偃蹇钓烟沙，不肯云台定等差。","汉室了无尘土在，满江风月自芦花。"]},{"t":"雨宿","f":"七言绝句","c":["雨宿疏篷不耐閒，蘋花菰叶老江干。","鹭飞欲下忽惊起，秋水新添一寸寒。"]},{"t":"将入仙都","f":"七言绝句","c":["客如我亦未为俗，著我于中何忝渠。","苦作春阴愁又绝，蕙花香冷雨疏疏。"]},{"t":"春词 其三","f":"七言绝句","c":["剪得春词不忍看，雨深怕近碧阑干。","春无些力吹成雪，未必杏花能耐寒。"]},{"t":"春词 其一","f":"七言绝句","c":["翠鼎香深旋作茶，馀酲牵梦几还家。","梦中记得春池绿，曾共丁宁下番花。"]},{"t":"春词 其二","f":"七言绝句","c":["花不知愁句又尘，晚寒独自倚栏频。","一分心事一分雨，春负予耶予负春。"]},{"t":"春词 其五","f":"七言绝句","c":["一春直是柳风流，只恁风流只恁愁。","客又不来寒食近，碧蘅红杜满芳洲。"]},{"t":"春词 其四","f":"七言绝句","c":["草色将寒上客衣，柔情只了得花飞。","湘帘不隔社公雨，百姓人家燕未归。"]},{"t":"春夜","f":"七言绝句","c":["酒不能多诗又尘，栏干月午奈何春。","天寒莫到海棠瘦，一夜东风吹倒人。"]},{"t":"春思 其一","f":"七言绝句","c":["无何桃李又成荫，水抱孤村岸岸深。","径草不锄随意绿，要观天地发生心。"]},{"t":"春思 其二","f":"七言绝句","c":["烟草茸茸匝岸齐，晴天凫浴喜清溪。","一春造化花开尽，大欠渠诗共品题。"]},{"t":"春思 其三","f":"七言绝句","c":["春风多可太忙生，长共花边柳外行。","与燕可泥蜂酿蜜，才吹小雨又须晴。"]},{"t":"春思 其二","f":"七言绝句","c":["杜鹃花落石阑干，新染晴波绿绕湾。","小立伫诗风满袖，一双睡鸭占春閒。"]},{"t":"春思 其一","f":"七言绝句","c":["杨柳生寒莫上楼，夕阳芳草泥人愁。","情知社近迎新燕，尽捲湘帘不下钩。"]},{"t":"春晚 其二","f":"七言绝句","c":["青梅如豆带烟垂，紫蕨成拳著雨肥。","只有小桥杨柳外，杏花未肯放春归。"]},{"t":"春晚 其三","f":"七言绝句","c":["山杏溪桃睡欲昏，青旗邀客过孤村。","杨花不肯随春去，惹住晴风自入门。"]},{"t":"春望","f":"七言绝句","c":["春深酒熟溪桥鼓，午过斋闻野寺钟。","花不知名香自永，倚风临水为谁容。"]},{"t":"春暮","f":"七言绝句","c":["卷中未有好诗看，草满池塘梦已阑。","客又不来春又暮，一帘新雨杏花残。"]},{"t":"昭仪春浴","f":"七言绝句","c":["红薇滴露护轻寒，微鬓香丝卸玉鸾。","只道春风庭掖秘，外间已作画图看。"]},{"t":"洞元小集","f":"七言绝句","c":["鹤骨清寒不受吹，白云侵砚懒题诗。","雨深更觅山寒甚，过了重阳菊未知。"]},{"t":"洞元观","f":"七言绝句","c":["窗林绿气冷香彝，山带斜晖半入溪。","幽鸟似嫌人至数，瞥然飞过隔林啼。"]},{"t":"独立 其二","f":"七言绝句","c":["从来人说天难做，才怨春阴又怨晴。","昨夜雷驱三尺水，更愁桥断不通行。"]},{"t":"独立 其一","f":"七言绝句","c":["村夫子挟兔园册，教得黄鹂解读书。","能记蒙求中一句，百般娇姹可怜渠。"]},{"t":"癸卯元日 其二","f":"七言绝句","c":["远色苍茫草际烟，春风也到雪崖边。","不知最后屠苏酒，增一年欤减一年。"]},{"t":"癸卯元日 其一","f":"七言绝句","c":["政坐聪明误乃翁，莫将鞭影戏儿童。","春皋本分扶犁手，共驾乌犍待岁丰。"]},{"t":"秋热 其一","f":"七言绝句","c":["蕴隆日日等西风，等得西风更蕴隆。","四十日秋无点雨，谁将消息到梧桐。"]},{"t":"秋热 其二","f":"七言绝句","c":["山气爞爞旱火光，墙头枯草半青黄。","饥肠惯作晴雷吼，且乞梧桐一夜凉。"]},{"t":"种芥","f":"七言绝句","c":["不论青紫已离离，烟湿春畦手自治。","一笑摩挲空洞腹，是间尽纳几须弥。"]},{"t":"种韭","f":"七言绝句","c":["下秧已觉齿生津，坐想堆盘雨夜春。","政恐厨人无变馔，庾郎贫不似吾贫。"]},{"t":"胡登仕送花 其二","f":"七言绝句","c":["红酣紫腻不胜春，肯上先生垫角巾。","芳草醉眠今老矣，惜花心在怕花嗔。"]},{"t":"胡登仕送花 其一","f":"七言绝句","c":["一年春是牡丹时，不负花时只有诗。","老去自知才思尽，枉分风月到山篱。"]},{"t":"贵妃夜游","f":"七言绝句","c":["凤靴又上玉花骢，恩在君王一笑中。","三十六宫瑶草碧，不知多少恨春风。"]},{"t":"贷钱买牡丹屏","f":"七言绝句","c":["作券西家贷子钱，略容书卷识春妍。","杜陵妇忍长贫面，誇与樵青亦自贤。"]},{"t":"赵佥见过不值有诗次韵 其二","f":"七言绝句","c":["向来曾管重湖月，五老当门但读书。","见说邦人犹感慨，恨予不学蔺相如。"]},{"t":"送刘仲子就试 其二","f":"七言绝句","c":["小技文章道未尊，入时新样更难论。","鹄袍才脱须重读，六籍久为场屋昏。"]},{"t":"送刘仲子就试 其一","f":"七言绝句","c":["竹雨梧风满袖凉，踏槐仍逐众人忙。","一觞共滴蟾蜍露，并遣五千书传香。"]},{"t":"送荔子方蒙仲 其一","f":"七言绝句","c":["风枝露叶走筠笼，玉润冰寒擘绉红。","自往胸中评史记，久闻格调略相同。"]},{"t":"送荔子方蒙仲 其二","f":"七言绝句","c":["曾识坡仙海上山，清冰寒露洗熇袢。","老天不与诗为地，却欠闽中住一番。"]},{"t":"送琴遂还楚东 其二","f":"七言绝句","c":["脚根踏地袈裟破，鼻孔撩天拄杖横。","归扫秋云趺足坐，荻花半落晚风晴。"]},{"t":"送琴遂还楚东 其一","f":"七言绝句","c":["一生坐与蛇添足，万事不如龟缩头。","亦笑军持太多事，孤桐自了月明秋。"]},{"t":"重午","f":"七言绝句","c":["重午无人肯访临，竹低沙浅绿连阴。","倚松自读离骚坐，一笑独醒江水深。"]},{"t":"重阳","f":"七言绝句","c":["帽不禁吹怯酒觞，只携老砚了重阳。","黄花未抵渊明瘦，却做离骚以上香。"]},{"t":"重宿储文","f":"七言绝句","c":["只有诗囊澹似僧，却嫌官屋冷于冰。","桃花尽赖春风笑，惯与刘郎面熟能。"]},{"t":"闻角","f":"七言绝句","c":["残角吹霜月欲斜，天寒无奈客思家。","不知野竹沧江上，开到梅梢第几花。"]},{"t":"除夜 其一","f":"七言绝句","c":["日月无根走弹丸，年来年去几椒盘。","秋崖老却浑閒事，老却梅花不耐寒。"]},{"t":"除夜 其四","f":"七言绝句","c":["春入荷葭坞亦奇，坞名不枉与天知。","绿章并按閒池沼，岂但乌台要勘诗。"]},{"t":"除夜 其二","f":"七言绝句","c":["莫嫌工部太侵寻，老杜称呼直到今。","我但六年难改口，不知老杜更年深。"]},{"t":"除夜 其五","f":"七言绝句","c":["幸有牛衣暖似春，可曾半字日边人。","不知相国何为者，撩得诸公屋大嗔。"]},{"t":"除夜 其五","f":"七言绝句","c":["不是催租夜打门，那知宝祐改新元。","人间测度春风意，李白桃红又一番。"]},{"t":"除夜 其六","f":"七言绝句","c":["尽处生机衮衮新，花情柳思已精神。","岁堂堂去谁能守，睡到明朝又是春。"]},{"t":"除夜 其三","f":"七言绝句","c":["春缸落面滑于油，旋泼醅来不用篘。","穷鬼相随政相熟，莫题荼垒恼渠休。"]},{"t":"除夜 其六","f":"七言绝句","c":["眼底童乌已七龄，吾伊略亦记群经。","丁宁莫就中书试，只可松边竹下听。"]},{"t":"除夜 其四","f":"七言绝句","c":["山中寒尽不知年，只道梅花欲雪天。","未到五更春已动，乾坤生意本无边。"]},{"t":"除夜 其三","f":"七言绝句","c":["更与梅花把一杯，醉题帖子等春来。","须臾便是隔年事，留得寒香一并开。"]},{"t":"除夜 其二","f":"七言绝句","c":["莫笑青衫霜叶枯，六年不改旧称呼。","人间书疏非吾事，菜缕春盘何处无。"]},{"t":"除夜 其一","f":"七言绝句","c":["雪片初飞岁已除，竹篱梅自可吾庐。","归来只有穷相守，未议移文送却渠。"]},{"t":"夏夜","f":"七言绝句","c":["河汉微明星乍稀，碧莲香湿袭人衣。","夜凉如水琉璃滑，自起开窗放月归。"]},{"t":"病中","f":"七言绝句","c":["折铛破釜底堪脩，纵使脩成已不侔。","谁与吾身自珍重，暮年药笼漫劳收。"]},{"t":"素馨","f":"七言绝句","c":["雪骨冰肌合耐寒，怕寒却不离家山。","老夫怀土与渠等，一钁移来得许顽。"]},{"t":"荼蘼 其二","f":"七言绝句","c":["手插春风十万条，野香落絮玉摇摇。","黄鹂莫误看花眼，等得南薰雪未消。"]},{"t":"荼蘼 其一","f":"七言绝句","c":["山径阴阴雨未乾，春风已暖却成寒。","不缘天气浑无准，要护荼蘼继牡丹。"]},{"t":"被劾 其二","f":"七言绝句","c":["谁将物命作勤渠，黄雀头行万里馀。","每为世情三太息，不知吾亦是苞苴。"]},{"t":"被劾 其一","f":"七言绝句","c":["鹿走山林尽自娱，宁知性命系庖厨。","一杯羹足为奇货，野弋山渔何处无。"]},{"t":"逢梅 其一","f":"七言绝句","c":["水仙婉弱山樊冗，自我视之儿女曹。","鲁直径令相伯仲，至今未敢广离骚。"]},{"t":"逢梅 其二","f":"七言绝句","c":["人言草没孤山冢，从此梅花不要诗。","却是未嫌吾辈在，一枝开过竹巴篱。"]},{"t":"部索印纸","f":"七言绝句","c":["瀑涧茶烟雪屋灯，乱家更入乱云层。","老僧今已倦行脚，不用维那吃饭凭。"]},{"t":"宿不老山 其一","f":"七言绝句","c":["未必催租能办诗，不妨扶老上烟霏。","彭仙一去夜坛冷，老鹤不归云自飞。"]},{"t":"宿不老山 其二","f":"七言绝句","c":["借得松风一觉眠，旋烧枯叶煮山泉。","人间蚁蛭王侯梦，不到梅花纸帐边。"]},{"t":"宿芳润用壁间韵","f":"七言绝句","c":["只为梧桐怨夜长，不知杨柳老年芳。","林梢一片过云雨，便作秋声占取凉。"]},{"t":"客饟银茄不敢送场屋士","f":"七言绝句","c":["秋风谁怒水中蟹，昨梦不疑杯里蛇。","迸齿清寒银粟粟，不随盐酪供毗耶。"]},{"t":"寄梅","f":"七言绝句","c":["枝北枝南恨未除，春风误到寿阳居。","诗家不识梅花讳，把做好看誇道渠。"]},{"t":"寄游山友人","f":"七言绝句","c":["不是山阴访戴船，真成迷局烂柯仙。","径行处用规摹取，归与都人作画传。"]},{"t":"寄越友 其一","f":"七言绝句","c":["茂竹脩林已陈迹，禹穴剡溪俱胜游。","秋风倘未理归梦，我欲买船官渡头。"]},{"t":"寄越友 其二","f":"七言绝句","c":["湖山掩映信乐国，烟雨凄迷非故乡。","青灯何日一杯酒，江头极目吴山长。"]},{"t":"寄题赵德成东岩 其三","f":"七言绝句","c":["空山谁可閒来往，自种梅花伴月明。","小筑便为身后计，此奇千古未忘情。"]},{"t":"寄题赵德成东岩 其二","f":"七言绝句","c":["人间无处著我辈，只可飞泉藓石边。","习气犹馀子虚赋，苦令猿鹤怨风烟。"]},{"t":"寄题赵德成东岩 其一","f":"七言绝句","c":["好山倒合诗人管，新出东岩付此公。","略向画图曾半面，石床定许听松风。"]},{"t":"寄题章氏起青楼 其一","f":"七言绝句","c":["结楼多与青山对，却是青山不对渠。","见说蜃岩排闼入，一窗晴色共残书。"]},{"t":"寄题章氏起青楼 其二","f":"七言绝句","c":["寒青拔起二千石，山是一分云一分。","切莫向渠谈世事，怕渠说与沈休文。"]},{"t":"得祠 其二","f":"七言绝句","c":["石床散发洒松风，安用黄冠累此翁。","但喜太平今有象，渔樵亦在万几中。"]},{"t":"得祠 其一","f":"七言绝句","c":["十年梦不到清都，云满寒蓑雪满颅。","一片青山一黄犊，底须更著旧称呼。"]},{"t":"悼栖云主人","f":"七言绝句","c":["羽士岩前烟树深，乱云堆屋自无心。","鹤惊蕙帐夜岑寂，霜月正寒愁不禁。"]},{"t":"晚秋犹热 其二","f":"七言绝句","c":["适自相遭各有时，莫悲团扇与秋辞。","班姬不死天无准，定悔当时作许悲。"]},{"t":"晚秋犹热 其一","f":"七言绝句","c":["九月年时已肃霜，今年九月尚追凉。","幸吾絺绤犹无恙，杜老何烦苦自伤。"]},{"t":"梅花 其四","f":"七言绝句","c":["茅茨烟水隔孤村，雪冷谁敲月下门。","只与梅花曾有旧，暗香时肯到洼尊。"]},{"t":"梅花 其三","f":"七言绝句","c":["雪压横枝卧浅波，三花五蕊不须多。","平生为尔添诗兴，今日无诗奈尔何。"]},{"t":"梅花 其一","f":"七言绝句","c":["竹绕疏篱水绕村，一枝无语更黄昏。","暗香似识骚人意，月澹无风自入门。"]},{"t":"梅花十绝 其十","f":"七言绝句","c":["竹缘货殖比封君，松爱微官不避秦。","至竟羞与哙等伍，岁寒谁障庾公尘。"]},{"t":"梅花十绝 其二","f":"七言绝句","c":["日日寻梅未肯春，几番和月倚吟身。","一枝斜入丛篁里，人不见渠渠见人。"]},{"t":"梅花十绝 其四","f":"词","c":["是处溪桥浅带流，山中别有一深幽。","规模略比林君复，开上风烟顶?头。"]},{"t":"梅花十绝 其一","f":"七言绝句","c":["尽道春风有等差，从前谩语待诗家。","今年雪屋亲曾见，的当南枝先著花。"]},{"t":"梅花十绝 其八","f":"七言绝句","c":["三分香有七分清，月冷霜寒太瘦生。","山泽之儒君识否，乐天姓氏谪仙名。"]},{"t":"梅花十绝 其五","f":"七言绝句","c":["自插斜枝垫角巾，诗狂又有老精神。","黄昏酒醒欲归去，月出山来唤住人。"]},{"t":"梅花十绝 其七","f":"七言绝句","c":["逋仙解道影南斜，二百年来蔑以加。","别有脱胎诗一句，自从梅后更无花。"]},{"t":"梅花十绝 其三","f":"七言绝句","c":["自有诗来几许诗，玉堂吹彻又茅茨。","阿谁不爱梅花句，未省梅花爱阿谁。"]},{"t":"梅花十绝 其六","f":"七言绝句","c":["老树生苔冻欲枯，山村雪意晚模糊。","一梢横打竹边过，造化工成水墨图。"]},{"t":"梦中 其一","f":"七言绝句","c":["凡我同盟鸥鹭群，既盟之后亦幽欣。","山中芝朮香堪煮，鹤未归来空暮云。"]},{"t":"梦中 其二","f":"七言绝句","c":["树擎晚色柔枝碧，兔睡晴香老月寒。","自滴玉蜍秋满袖，轻云片片泊阑干。"]},{"t":"梦中","f":"七言绝句","c":["屋头晴哢已交交，更向春风打一遭。","花片已肥红欲绽，柳丝烟重绿如缫。"]},{"t":"梦过湖","f":"七言绝句","c":["万柄风荷秋渺然，百钱又买过湖船。","菰蒲鸥鹭浑相识，惊怪人间已十年。"]},{"t":"梦放翁为予作贫乐斋扁诚斋许画斋壁予本无是斋亦不省诚斋之能画也","f":"七言绝句","c":["晴窗欲晓鸟声春，唤起藜床入定身。","老去不知三月暮，梦中亲见两诗人。"]},{"t":"清明","f":"七言绝句","c":["淡烟疏雨清明日，飞絮落花游子心。","燕话春愁初睡起，一帘草色暮池深。"]},{"t":"清明日舟次吴门 其二","f":"七言绝句","c":["片片飞花更异乡，人家插柳抵愁长。","晴沙烟草几今古，春去春来燕子忙。"]},{"t":"清明日舟次吴门 其一","f":"七言绝句","c":["篷窗恰受夕阳明，杨柳梨花半月程。","老去不知寒食近，一篙烟水载春行。"]},{"t":"渔父词 其二","f":"七言绝句","c":["阴阴深树晚生烟，雨急归来失系船。","白鹭不惊沙水浅，依然共在绿杨边。"]},{"t":"渔父词 其三","f":"七言绝句","c":["烟波渺渺一轻篷，浦溆生寒芦荻风。","昨夜新霜鱼自少，满江明月笛声中。"]},{"t":"渔父词 其四","f":"七言绝句","c":["沽酒归来雪满船，一蓑撑傍断矶边。","谁家庭院无梅看，不似江村欲暮天。"]},{"t":"渔父词 其一","f":"七言绝句","c":["晚晴铺网占鸥沙，各自分鱼就酒家。","洞口醉眠船正暖，碧桃流出两三花。"]},{"t":"猫叹","f":"七言绝句","c":["雪齿霜毛入画图，食无鱼亦饱于菟。","床头鼠辈翻盆盎，自向花间捕乳雏。"]},{"t":"祷晴福善 其三","f":"七言绝句","c":["背犊腰牛忽解颜，摩挲一饱政相关。","王于霓望无终极，孰与侯邦年岁间。"]},{"t":"祷晴福善 其一","f":"七言绝句","c":["稻压田塍米似珠，老农为说几年无。","一晴不费君王力，莫等香烟上化炉。"]},{"t":"祷晴福善 其二","f":"七言绝句","c":["夜落檐花未肯晴，灯寒等不到天明。","自怜短发垂垂老，一滴秋霖白一茎。"]},{"t":"雪中","f":"七言绝句","c":["行缠不了醉生涯，空宿沙头卖酒家。","最是晓寒吟未稳，雪深无面见梅花。"]},{"t":"雪中观梅","f":"七言绝句","c":["落尽梅花合一杯，雪深无复旧莓苔。","山溪莫遣人行破，安得酒从天上来。"]},{"t":"雪中迓新宪","f":"七言绝句","c":["踏碎琼瑶千里寒，新年才此试吟鞍。","不须更说逢迎恶，只作灞桥诗兴看。"]},{"t":"雪后草亭","f":"七言绝句","c":["梅花面目冷于冰，亦笑山翁草作亭。","一夜雪寒重整过，碧琉璃瓦水晶钉。"]},{"t":"雪后梅边 其六","f":"七言绝句","c":["小小茅亭面面寒，玉花能薄雪花乾。","今年不是开迟著，等得群花比并看。"]},{"t":"雪后梅边 其十","f":"七言绝句","c":["春风且莫一齐开，留与山翁逐日来。","只恐难将冰雪面，伴渠桃李并尘埃。"]},{"t":"雪后梅边 其一","f":"七言绝句","c":["老来筋力倦登山，契阔梅花几日间。","莫与梅花筋力倦，且推一雪阻跻攀。"]},{"t":"雪后梅边 其八","f":"七言绝句","c":["野径茅茨竹作墙，岁寒曾亦几平章。","高人风味天然别，不在横斜不在香。"]},{"t":"雪后梅边 其三","f":"七言绝句","c":["半身苍藓雪槎枒，直到顶头才数花。","看尽玉林山上下，还须渠是当行家。"]},{"t":"雪后梅边 其二","f":"七言绝句","c":["与君只隔竹笆篱，踏雪过从自一奇。","开口便遭花问当，老夫愧面了无辞。"]},{"t":"雪后梅边 其四","f":"七言绝句","c":["花中淡伫只梅花，未见梅中萼绿华。","一色琼瑶裾织翠，尚嫌红蜡蒂村些。"]},{"t":"雪后梅边 其九","f":"七言绝句","c":["寒雀群飞最上头，啄残香玉翠云裘。","老坡诗里么么凤，待与梅花渠是不。"]},{"t":"雪后梅边 其七","f":"七言绝句","c":["一枝密密一枝疏，一树亭亭一树枯。","月是毛锥烟是纸，为予写作百梅图。"]},{"t":"雪后梅边 其五","f":"七言绝句","c":["玉蕤五出是天姿，六出时时更绝奇。","夜半同参雪花去，春风元自不曾知。"]},{"t":"堪笑 其三","f":"七言绝句","c":["堪笑刘安苦学仙，云中鸡犬事茫然。","早知官职乃如许，悔不人间差自贤。"]},{"t":"堪笑 其五","f":"七言绝句","c":["堪笑张华死不休，谩精象数古无俦。","中台星拆何曾识，祗识龙泉动斗牛。"]},{"t":"堪笑 其四","f":"七言绝句","c":["堪笑山阳汉鼎移，智如文若岂难知。","定嫌佐命居人后，略一昌言死亦痴。"]},{"t":"堪笑 其一","f":"七言绝句","c":["堪笑平原血溅衣，但知忠义未知机。","命悬鬼貌千秋事，年及悬车自不归。"]},{"t":"晴梦","f":"七言绝句","c":["尘土侵人懒出门，小窗容我负晴暾。","梦骑瘦马寻诗去，曾到梅花深雪村。"]},{"t":"暑中杂兴 其五","f":"七言绝句","c":["是非不到野溪边，只就梧桐听雨眠。","睡熟不知溪水长，鹭鸶飞上钓鱼船。"]},{"t":"暑中杂兴 其八","f":"七言绝句","c":["只锄蔬甲亦妨閒，久与溪云断往还。","今日偶来僧却在，共煎茶吃话庐山。"]},{"t":"暑中杂兴 其三","f":"七言绝句","c":["今年不上一竿竹，渠岂于人亦世情。","风雨尚馀千个在，结巢吾欲听秋声。"]},{"t":"暑中杂兴 其一","f":"七言绝句","c":["一刻之间值万金，苦无人可共幽襟。","几年不作西湖想，听得啼莺不自禁。"]},{"t":"暑中杂兴 其二","f":"七言绝句","c":["不惯山中夜月寒，满窗树影藓花乾。","移床近壁不敢卧，恐是龙蛇之屈蟠。"]},{"t":"游九曲 其一","f":"七言绝句","c":["掀蓬仰看玉峥嵘，借得渔船一日晴。","九曲水穷山雨急，老仙于我岂无情。"]},{"t":"游九曲 其二","f":"七言绝句","c":["鹤怨空山久勒文，买船又访武夷君。","一声铁笛不知处，但觉满身生白云。"]},{"t":"游九曲 其三","f":"七言绝句","c":["莫问神仙定有无，地灵断不著凡夫。","我来便觉芒鞋好，飞上前山不用扶。"]},{"t":"湖上八首 其一","f":"七言绝句","c":["沙暖鸳鸯傍柳眠，春来亦懒避湖船。","佳人窈窕惜颜色，自照晴波整翠钿。"]},{"t":"湖上八首 其二","f":"七言绝句","c":["今岁春风特地寒，百花无赖已摧残。","马塍晓雨如尘细，处处筠篮卖牡丹。"]},{"t":"湖上八首 其八","f":"七言绝句","c":["鞦韆人散雨千丝，谁把秦笙隔院吹。","但觉小桥烟外柳，春风无力逞腰支。"]},{"t":"湖上八首 其五","f":"七言绝句","c":["春连禁籞绿阴交，对面晴烟舞翠蛟。","最是君王游幸少，宫花浑未识鸣鞘。"]},{"t":"湖上八首 其四","f":"七言绝句","c":["绿波如画雨初晴，一岸烟芜极望平。","日暮落花风欲定，小楼弦管压新声。"]},{"t":"湖上八首 其六","f":"七言绝句","c":["连天芳草晚凄凄，蹀躞花边马不嘶。","蜂蝶已归弦管静，犹闻人语画桥西。"]},{"t":"湖上八首 其三","f":"七言绝句","c":["轻尘不动雨霏微，堤外芹香燕子飞。","庭院日长帘幕静，含情脉脉看春归。"]},{"t":"湖上八首 其七","f":"七言绝句","c":["游人抵死爱春韶，风暖花香酒未消。","须向先贤堂上去，画船无数泊长桥。"]},{"t":"湖上醉题","f":"七言绝句","c":["山知吾亦以诗豪，畴昔于山只淡交。","清得不多赢得瘦，一生悔读楚离骚。"]},{"t":"湖山纪游 其一","f":"七言绝句","c":["两山南北诗三百，付与秋风赵倚楼。","忽忆老逋坟下路，梅花夜雪上孤舟。"]},{"t":"湖山纪游 其二","f":"七言绝句","c":["凤凰城里花如海，选集诸人守部门。","此老久渔双脚浪，岛烟湖雾又黄昏。"]},{"t":"紫虚观","f":"七言绝句","c":["小炷炉熏待瀹茶，瓦盆添水养蒲芽。","江南地暖得春早，开尽雪篱无数花。"]},{"t":"谢人致蟹 其三","f":"七言绝句","c":["雪砍双螯玉一壶，樵中曾有此奇无。","始知张翰思归意，不为秋风只为鲈。"]},{"t":"谢人致蟹 其一","f":"七言绝句","c":["樵岚无蟹有监州，已负诗肠过一秋。","莫怪渊明便归去，得渠自合老菟裘。"]},{"t":"谢人致蟹 其二","f":"七言绝句","c":["此去江头只两程，寒蒲解缚便横行。","无肠政要空虚腹，满贮芦花与月明。"]},{"t":"谢人致蟹 其四","f":"七言绝句","c":["除却金齑霜后枨，更无一物可诗情。","诚斋配以彭生脔，岂不冤哉五鼎烹。"]},{"t":"跋至能所书西湖洞天事 其二","f":"七言绝句","c":["圮上老人亲堕履，衡山道士共联诗。","向来此事亦多矣，我故于君了不疑。"]},{"t":"跋至能所书西湖洞天事 其一","f":"七言绝句","c":["西湖天下奇绝处，定有老仙时下观。","重来俯仰已陈迹，但见孤山烟雾漫。"]},{"t":"道中即事 其二","f":"七言绝句","c":["家人不寄扊扅诗，直恐藁砧官尚微。","到了不过相爱耳，未论此语是耶非。"]},{"t":"道中即事 其十三","f":"七言绝句","c":["剡溪船后灞桥驴，著我荒村一笋舆。","却后几年俱作画，未知雪句定何如。"]},{"t":"道中即事 其七","f":"七言绝句","c":["对灶何妨客燎衣，溪翁且莫键柴扉。","日之夕矣樵风冷，觳觫一牛将犊归。"]},{"t":"道中即事 其十","f":"七言绝句","c":["野涨平溪已断桥，悔将辛苦上岧峣。","朝来雨断才堪厉，依旧绿杨山径遥。"]},{"t":"道中即事 其五","f":"七言绝句","c":["荦确连云路不分，云侵衫袖白纷纷。","亦知云自青山出，不见青山只有云。"]},{"t":"道中即事 其六","f":"七言绝句","c":["冲雨冲风莫管渠，晨炊蓐食便巾车。","能无几日到茅舍，睡到日高相折除。"]},{"t":"道中即事 其四","f":"七言绝句","c":["梅已飘零尚典刑，断魂篱落野烟青。","灵均憔悴乃知此，到老可人宁独醒。"]},{"t":"道中即事 其九","f":"七言绝句","c":["画中亦爱雨中山，连雨山行却厌看。","一夜东风吹作雪，问谁画我访袁安。"]},{"t":"道中即事 其十一","f":"七言绝句","c":["晨光漏日鸟深春，况此泥行雨宿人。","夜半瓦鸣惊梦觉，悔将蓬笠当劳薪。"]},{"t":"道中即事 其八","f":"词","c":["上到春山顶?头，更携烟雨入吾州。","梅花便作乡人看，飞落酒杯相劝酬。"]},{"t":"道中即事 其三","f":"七言绝句","c":["十日山寒雨不休，仆其痡矣得无愁。","老夫自爱归程好，肯为春泥怨鹁鸠。"]},{"t":"道中即事 其一","f":"七言绝句","c":["春泥滑滑欲溅裾，肯为梅花顾草庐。","唤作诗人看得未，雨籉笠雪一肩舆。"]},{"t":"雁来红 其二","f":"七言绝句","c":["秋入山篱叶正丹，老天浑误作花看。","不知宋玉今何似，雁欲来时霜正寒。"]},{"t":"雁来红 其一","f":"七言绝句","c":["是叶青青花片红，剪裁无巧似春风。","谁将叶作花颜色，更与春风迥不同。"]},{"t":"溪店回文","f":"七言绝句","c":["啼莺几处垂垂柳，乳燕双飞片片花。","溪浅度云山带雨，岸崩攲树草连沙。"]},{"t":"简徐宰 其四","f":"七言绝句","c":["俗吏相传作县难，及民那有一分宽。","闻君犹逮从诸老，说到民贫鼻亦酸。"]},{"t":"简徐宰 其三","f":"七言绝句","c":["西山有蕨北山薇，荷雨锄烟不疗饥。","但得县官如卓鲁，此言只恐未曾知。"]},{"t":"简徐宰 其二","f":"七言绝句","c":["自织春蓑学治田，山寒辛苦不逢年。","摩挲此腹何时饱，黄犊夕阳相对眠。"]},{"t":"简徐宰 其一","f":"七言绝句","c":["雨外茅茨黄叶村，老农相语一灯昏。","山深未识新官姓，但说无人夜打门。"]},{"t":"蒙恩予祠 其二","f":"七言绝句","c":["月明弄影雪巅癯，只似胡僧不似吾。","忽予牙绯称羽客，道官儒黻释头颅。"]},{"t":"蒙恩予祠 其一","f":"七言绝句","c":["坚卧牛庵饱岁寒，恩书初许作黄冠。","孙仙彭老如相问，筋力犹堪上醮坛。"]},{"t":"赪桐花 其二","f":"七言绝句","c":["似子圆红不似花，绿丛擎出野人家。","亦知吟骨今当换，火候初成独体砂。"]},{"t":"嘲鹭","f":"七言绝句","c":["曾有诗矜白鹭閒，一生诗眼乞山漫。","朝来更觉忙于我，雪冱苍溪不道寒。"]},{"t":"题八士图 其一","f":"七言绝句","c":["雅闻八士春俱秀，未觉三贤迹已陈。","投分不论曾识面，此图到手便情亲。"]},{"t":"题八士图 其二","f":"七言绝句","c":["飞絮游丝芳草路，淡烟疏雨落花天。","偶然画出寻诗意，未必新诗待画传。"]},{"t":"题甘露寺中峰 其一","f":"词","c":["六朝晴树一江秋，尽入风烟顶?头。","老手更擎江色出，小亭景却胜于楼。"]},{"t":"题甘露寺中峰 其二","f":"七言绝句","c":["金焦两点自东西，著我于中亦一奇。","菰叶蘋花秋共晚，山寒未必白鸥知。"]},{"t":"题郑尉爱山楼 其二","f":"七言绝句","c":["三间屋与佛同住，纸帐梅花烟雨寒。","有客肯来清话否，上楼借与好山看。"]},{"t":"题郑尉爱山楼 其一","f":"七言绝句","c":["青山不入俗士眼，谁肯著楼招唤渠。","径草不锄花又老，一帘新雨了残书。"]},{"t":"题赵漕小蓬莱 其二","f":"七言绝句","c":["老夫曾到道家山，太乙青藜夜叩关。","著作承明今付子，仙壶元不隔人间。"]},{"t":"题赵漕小蓬莱 其一","f":"七言绝句","c":["乾坤不尽一蘧庐，方寸中间几太虚。","办著海涛三万里，乃翁底用费分疏。"]},{"t":"题致堂新州坐石 其一","f":"七言绝句","c":["苍寒瘴面新州石，直不话头传不休。","秦负儒耶君误矣，二书今与大江流。"]},{"t":"题致堂新州坐石 其二","f":"七言绝句","c":["棱层不隔梅花岭，万里相从识两翁。","却怪牧牛亭下路，石麟咫尺卧秋风。"]},{"t":"题郭氏继一堂 其二","f":"七言绝句","c":["渔蓑钓艇越中居，底处烟波不属渠。","一曲鉴湖须敕赐，却令鸥鸟费分疏。"]},{"t":"题偶爱 其二","f":"七言绝句","c":["长汀宜日山宜雨，尽在鸥看鹭听中。","想见夜寒留客醉，倚阑拍手唤渔篷。"]},{"t":"题偶爱 其一","f":"七言绝句","c":["每评吾郡佳山水，当以水西为最奇。","径向水西非具眼，不眠偶爱不渠知。"]},{"t":"题偶爱 其四","f":"七言绝句","c":["溪云莫怪尘埃面，更与青山把一杯。","未省此诗容写否，闻渠曾识谪仙来。"]},{"t":"题偶爱 其三","f":"七言绝句","c":["随行茶灶曾同宿，看尽朝岚与夕霏。","一片诗愁秋渺渺，树林深处见僧归。"]},{"t":"题雄观","f":"七言绝句","c":["送出青山点点愁，数声柔橹隔沧洲。","白鸥不受人间暑，明月一江天地秋。"]},{"t":"赠写照吴生 其一","f":"七言绝句","c":["山须未压棱层骨，诗不能平磊磈胸。","烦画雪溪诗意思，梅花苍石一横筇。"]},{"t":"赠写照吴生 其二","f":"七言绝句","c":["几人堪画麒麟阁，万事不如鹦鹉杯。","只谓故吾诗瘦耳，寒沙鸥鹭莫惊猜。"]},{"t":"赠诗僧 其二","f":"七言绝句","c":["从来佛法无多子，底用芒鞋半九州。","赢得诸人诗满袖，草深一丈法堂秋。"]},{"t":"赠诗僧 其一","f":"七言绝句","c":["瀑泉癞可能诗最，毕竟难为本色僧。","要识庐山真面目，一溪明月冷于冰。"]},{"t":"赠相士","f":"七言绝句","c":["老来学剑已无成，眼底边尘猝未清。","此辈束之高阁耳，且容黄犊伴春耕。"]},{"t":"赠谈命苏秦","f":"七言绝句","c":["一蓑牛背饱看山，扣角前冈烟雨寒。","客自纵横三尺觜，与吾烟雨不相干。"]},{"t":"赠谈命者赵生自号千两金","f":"七言绝句","c":["人间万事一杯酒，之子五行千两金。","听我自穷诗自老，半江明月苇花深。"]},{"t":"赠算数汪生 其二","f":"七言绝句","c":["貂蝉勋业麒麟画，自有夔龙向上人。","数本不为吾辈设，风烟之句水云身。"]},{"t":"赠算数汪生 其一","f":"七言绝句","c":["十年不读床头易，山雨鸣蓑为口忙。","行矣公无落吾事，水田漠漠正移秧。"]},{"t":"擘蟹","f":"七言绝句","c":["秋来何但食无鱼，老去宁须腹有书。","空洞略容君几辈，草泥郭索一从渠。"]},{"t":"鹭","f":"七言绝句","c":["耸两吟肩似我愁，菰蒲叶下一身秋。","溪风昨夜吹鱼落，飞过前滩看水流。"]},{"t":"羹莼","f":"七言绝句","c":["烟雨中间几白鸥，藕花菱叶小亭幽。","紫莼共煮香涎滑，吐出新诗字字秋。"]},{"t":"乙酉岁游浙中道闻盗起霅川遂寓珠溪","f":"七言律诗","c":["未到山阴兴已阑，相传道路正间关。","故人坐隔月千里，老宿肯分云半间。","有客谁家无白酒，能诗何处不青山。","一声啼鸟长廊静，花落花开春自閒。"]},{"t":"七夕","f":"七言律诗","c":["明河此夕会双星，滓秽圆清太不经。","牛岂其然耕觳觫，女何为者嫁娉婷。","閒中但觉人间巧，老去谁邀帝子灵。","千古文章柳州事，解将蹇拙说惺惺。"]},{"t":"七夕郑文振席上姬有楚云者为作三弄","f":"五言律诗","c":["帝子经年别，秋风远客情。","断云含宿雨，古木落寒声。","河汉低逾润，江潮夜未平。","巫云莫吹笛，吾意正凄清。"]},{"t":"七夕潘宰招不往","f":"七言律诗","c":["投老归欤拙独存，剖瓜亦欲问天孙。","故人有约夜堂醉，老子不禁秋暑袢。","却恐长绳縻日月，政须高枕问乾坤。","北窗风好难为客，未辨冠巾数候门。"]},{"t":"九日","f":"七言律诗","c":["把住秋云绕菊篱，野情未觉老垂垂。","古今不遇岂惟我，风雨相过莫问谁。","未郭索前空有酒，自陶潜后久无诗。","底须计较明年健，只么悠然自一奇。"]},{"t":"九日","f":"五言律诗","c":["逢人提菊卖，方省是重阳。","山晓雨初霁，江秋树亦凉。","年华犹故我，烽火更殊乡。","有客那无酒，令人忆草堂。"]},{"t":"九日与同年沈贯卿饮月墅","f":"七言律诗","c":["自摘黄花插满头，谁怜白发不禁秋。","同年肯过卢仝屋，九日共登王粲楼。","天气政为吾辈设，酒香莫对俗人篘。","渠侬尽把茱萸看，更与渊明风马牛。"]},{"t":"九日道中","f":"七言律诗","c":["重阳却喜无风雨，野菊迎人亦自花。","年去年来秋又老，江南江北鬓将华。","离骚如此那无酒，羁旅虽谙不似家。","但得东篱堪种菊，尽容吾子岸乌纱。"]},{"t":"九日集清凉佳处","f":"七言律诗","c":["老笔盘空墨未乾，最佳处与著危栏。","江山分与诸贤管，风雨专为九日寒。","白发自惊秋节序，黄花曾识晋衣冠。","未须计较明年健，别做茱萸一等看。"]},{"t":"人日 其二","f":"词","c":["赖有空山著此翁，不然高论与谁同。","百年会尽玄尚白，一气不停春又红。","诗卷每随烟水外，鸟声多在夕阳中。","年丰已卜晴人日，亦是平生?亩忠。"]},{"t":"人日吴明辅招不往","f":"七言律诗","c":["江湖老我百无堪，懒过紬书太史谈。","雨脚又连人日暗，酒肠那似少年酣。","一生出处龟藏六，万事乘除狙赋三。","且试半篙春水绿，南山之北北山南。"]},{"t":"入局","f":"七言律诗","c":["雁鹜行馀纸尾钳，岸湖老屋压题签。","印文生绿空藏匮，草色蟠青欲刺檐。","茶话略无尘土杂，荷香剩有水风兼。","官曹那得閒如此，亦奉一囊惭属厌。"]},{"t":"入歙","f":"五言律诗","c":["野竹吾乡路，逢人似故知。","社寒催燕早，夜雨勒花迟。","草入思连梦，山邀到歙诗。","客中春一半，煞是负春彝。"]},{"t":"八月十四月食中秋遂无月","f":"七言律诗","c":["妖蟆不为中秋地，老兔先奔昨夜寒。","世事相违剧晴雨，人生何苦许悲欢。","云窗自照青藜杖，月户重修白玉盘。","坐想西风万袍鹄，政飞健笔写琅玕。"]},{"t":"十二月二十四日雪盖予三年于淮才见此耳时东师援淝水捷书西来走笔呈赵公借官奴与幕友一醉","f":"七言律诗","c":["淝水风声欲破苻，文城雪意趁禽吴。","诗筒拟醉玉跳脱，捷羽已飞金仆姑。","剡曲但能乘兴逸，灞桥仅不负诗癯。","那知莫府文书外，更解飞琼打阵图。"]},{"t":"十二月十日","f":"七言律诗","c":["酒醒开门雪满山，径穿疏竹上危栏。","溪山与我俱成画，草树惟梅大耐寒。","留伴夜深银凿落，莫缘春近玉阑珊。","老枝擎重供诗嚼，一洗相如渴肺肝。"]},{"t":"十月六日园丁置墨紫","f":"七言律诗","c":["已是年时欲雪天，谁回冷落作芳妍。","极知品在群葩上，忽与梅争一著先。","颜色依然香墨重，花头不减暮春圆。","人言桃李多如此，有底能移造化权。"]},{"t":"又用胡尉韵","f":"七言律诗","c":["便觉寻春负一筹，老怀无复少年游。","茶桑天似鹅黄酒，杨柳花飞狐白裘。","试问独醒观众醉，何如一笑失千忧。","不知多少人间事，付与溪声自在流。"]},{"t":"又次韵 其二","f":"七言律诗","c":["绿阴政自可羸骖，舴艋何堪暑气惔。","沙碛稍凉客且住，水程虽远未须贪。","吾侪焉往不三黜，此段无劳忍一惭。","山际有田归自好，休论暮四与朝三。"]},{"t":"又次韵 其一","f":"七言律诗","c":["半夜江城久已谙，白鸥眠处落烟帆。","诗穷政有牛腰轴，身散宁为马口衔。","时以酒浇胸磊磊，或嫌山似面岩岩。","春田芜没归耕是，待与丰年赋载芟。"]},{"t":"三用韵酬沈同年","f":"七言律诗","c":["两屦适从何许来，双蓬无处避风埃。","江湖谁共月千里，轩冕真同水一杯。","纵有穷愁侵病骨，断无荣辱到灵台。","只销处士星明润，未用三台入斗魁。"]},{"t":"三用韵酬诸丈","f":"七言律诗","c":["家在江南黄叶村，归来重葺柳边门。","溪云排闼砚犹湿，山溜通池水自喧。","但得梅花容著语，无烦桃叶为开尊。","逢迎车马荷衣老，面目何堪向绮园。"]},{"t":"三岩","f":"七言律诗","c":["山入苍州翠作层，何年凿此玉崚嶒。","瀑从峭壁飞将落，雪冱苍崖危欲崩。","寺老尚堪支古佛，地灵不肯著凡僧。","定应嫌客留名姓，云逼人寒一砚冰。"]},{"t":"上巳修禊社谢两园","f":"七言律诗","c":["海棠过了只垂杨，合与良辰卜醉乡。","定胜永和三月禊，并游社谢两流觞。","定州刻石犹真赝，晋代衣冠今在亡。","陶写岂无丝竹在，不酬酒渴与诗狂。"]},{"t":"上巳溪汎","f":"七言律诗","c":["舴艋舟轻暖欲酣，鸬鹚杓重老何堪。","风霜两鬓五十五，杨柳几番三月三。","禊帖又逢今癸丑，兰亭仍是旧东南。","死生政亦寻常事，却笑诸贤苦未谙。"]},{"t":"上元大雪重赋","f":"七言律诗","c":["愁霖半月办此雪，元夕山城特地寒。","顿有园林春富贵，略无灯火夜阑珊。","年饥那得花成市，天巧聊将玉作栏。","百紫千红生意动，不知后土几时乾。"]},{"t":"上冢 其二","f":"七言律诗","c":["一杯麦饭洒悲辛，不尽烟芜旧与新。","地下岂无担板汉，世间但有乞墦人。","荼蘼芍药几何日，寒食清明又一春。","自是老怀多感慨，非干芳草负蹄轮。"]},{"t":"与客观雪 其三","f":"七言律诗","c":["肺渴初供醒酒冰，又思携客上峥嵘。","十分宇宙无尘事，一色琼瑶是化城。","病起未堪论斗醉，诗狂且莫到参横。","剡溪可是忙回棹，冻合琉璃作么生。"]},{"t":"与客观雪 其一","f":"七言律诗","c":["鹤帐奇寒被欲冰，开门千嶂雪峥嵘。","频年无此丰年玉，一夜移将不夜城。","富贵园林行树密，模糊水墨画图横。","与诗小住为佳耳，莫管梅花太瘦生。"]},{"t":"与客观雪 其二","f":"七言律诗","c":["未怕风威酒亦冰，凭虚吞以气峥嵘。","何人出此六奇计，我辈贤于五字城。","松压钓蓑银独速，麦分棋局玉纵横。","自然石鼎煎鱼眼，解致邹枚汉两生。"]},{"t":"乞梅花","f":"七言律诗","c":["晚云撩乱商量雪，家傍梅花合有诗。","不寄一枝春苦吝，相思五夜梦先知。","乘云而下惟姑射，得圣之清者伯夷。","已戒管城三盥沐，讵令空手对冰姿。"]},{"t":"大雨","f":"七言律诗","c":["蛰龙怒欲起春霆，并挟髯虬上杳冥。","老色干云鳞甲动，苍皮粘雹爪痕腥。","物方神变谁能测，山不高深亦有灵。","谁与护持诗墨在，略无风雨损吾亭。"]},{"t":"子鱼","f":"七言律诗","c":["桃花水暖正鱼肥，子胀连胞迸腹腴。","黄栗玉燖春寸寸，水晶盐醋粟铢铢。","鲛人泣下甘孥戮，龙伯刑淫并孕刳。","老子胸中兵百万，酒船不枉到江湖。"]},{"t":"小集次韵","f":"七言律诗","c":["才能诗便不能閒，与客提壶且看山。","紫翠夕阳烟漠漠，绿阴深树鸟关关。","酒杯不负林泉约，春事已非桃李颜。","我醉欲眠君莫去，竹间自有月三间。"]},{"t":"山中 其五","f":"七言律诗","c":["暄风已惬绿阴凉，小簟初横六尺床。","如宇宙宽容膝地，与尘埃隔及肩墙。","鸟乌声乐樱桃熟，田舍人忙麦饭香。","留得壁间双不借，尚堪锄水共移秧。"]},{"t":"山中 其三","f":"七言律诗","c":["野烟啼鸟各忻然，一枕山篱又几年。","不可奈何天有命，久当已矣世无缘。","跨牛仰面自横笛，骑鹤缠腰那办钱。","芦苇秋声石桥月，只餐荷气亦成仙。"]},{"t":"山中 其四","f":"七言律诗","c":["半坞幽深近物情，一筇老健惬山行。","月于水底见逾好，风打松边过便清。","鹤睡不惊舂药臼，鸟啼时作读书声。","山翁两手浑无用，只把犁锄做太平。"]},{"t":"山中 其一","f":"七言律诗","c":["寂莫空山久掩扉，残书谁与解重围。","推豗时作橐驼坐，恍惚化为蝴蝶飞。","春事已归双雪鬓，生涯尽在一荷衣。","夜寒扣角悲声壮，但得牛肥道亦肥。"]},{"t":"山中 其二","f":"七言律诗","c":["茅葺山堂竹打篱，尚馀老鹤共襟期。","一生朝市几何日，五亩园林都是诗。","身后谁浇胸磊磊，命中不带印累累。","薄田有秫聊堪酿，尽足秋崖作受持。"]},{"t":"山中 其六","f":"七言律诗","c":["无心出岫懒于云，生死交情一付君。","五柳当门陶令宅，百梅共坞老逋坟。","山虽甚浅略堪隐，砚不能灵并可焚。","我亦平生轻俗子，向来鱼鸟自同群。"]},{"t":"山中 其八","f":"七言律诗","c":["只合空山著此身，野猿骨相鹤精神。","何关亲戚傥来物，自笑痴顽向上人。","手可持杯宁是病，瓶犹储粟未为贫。","公卿满壁非无画，不画公卿画钓缗。"]},{"t":"山中 其二","f":"七言律诗","c":["十亩荒园斸野烟，蔬畦麦陇带平田。","相忘鱼鸟无馀地，自信貂蝉有老天。","静处亦忙诗意思，贫中之乐酒因缘。","梅花不隔前村路，只在霜桥雪屋边。"]},{"t":"山中 其一","f":"七言律诗","c":["久无筋力踞虬龙，西崦东塘漫倚筇。","白练带随红练带，木夫容并水夫容。","宁消几两生前屐，忽忆当年饭后钟。","孤负草堂今夜月，径眠谁与吐奇胸。"]},{"t":"山中 其二","f":"七言律诗","c":["解缨聊复濯沧浪，晞发松阴藓石床。","有味是贫琳馆俸，无功于懒玉函方。","自参老子鼻端白，未羡诸公腰下黄。","蔗境渐佳惟习静，笔床茶灶并荒唐。"]},{"t":"山中 其四","f":"七言律诗","c":["漫道高眠昼掩关，南冈北岭几曾閒。","隰桑已作虾䗫眼，山笋时窥虎豹斑。","一味懒堪医传僻，五穷技不害诗孱。","著身何幸山岩里，多阅人间百险艰。"]},{"t":"山中 其七","f":"七言律诗","c":["寂寂门无长者车，穿深逗密惬幽居。","花能红白锦相似，山自青苍画不如。","鹤骨政应先狗马，雏孙殊未辨龙猪。","皇天老眼何缘错，高枕松风莫管渠。"]},{"t":"山中 其二","f":"七言律诗","c":["消閒未必在林泉，要自胸中别有天。","面壁九年曾悟道，观棋一局偶成仙。","不知老圃风烟外，请祝圣人香火缘。","莫道秋崖长是懒，无求何处不超然。"]},{"t":"山中 其五","f":"七言律诗","c":["剩斸荒寒地百弓，尽供弄月与吟风。","太平世界丰登外，小有洞天閒适中。","野服染成驼样褐，山花开到雁来红。","夕阳篱落谁呼唤，盂酒蹄肩赛社翁。"]},{"t":"山中 其一","f":"七言律诗","c":["世间尘土隔丘林，竹绕松园不厌深。","一片野云人寂寂，几番山雨夜沈沈。","桑麻事业本来面，竹帛功名过去心。","持戒十年今始定，邯郸梦不到寒衾。"]},{"t":"山中 其一","f":"七言律诗","c":["此身只合著林泉，安得缠腰十万钱。","百事懦无拖地胆，一生愚似信天缘。","青山有约不知老，黄犊与人相对眠。","问讯春蓑故无恙，乱云深处更超然。"]},{"t":"山中 其三","f":"七言律诗","c":["已付身心毕竟空，念头了不到穷通。","既愚宁免日三省，是圣未妨时一中。","物外禽鱼相尔汝，生前乌兔几西东。","谁云双手都无用，自种山田岁便丰。"]},{"t":"山中 其三","f":"七言律诗","c":["草草庵居绝似僧，不同劣有发鬅鬙。","空山一夜雷驱雨，老屋四围云拥灯。","诗骨瘦来人似鹤，书幐懒去字如蝇。","开门桃李俱尘土，春到园林曾不曾。"]},{"t":"山中 其二","f":"七言律诗","c":["溪村杨柳好藏鸦，春水池塘已吠蛙。","诗外共谁千里月，雨中老却一山花。","蝶将梦去客攲枕，燕寄声来社到家。","数掩断篱春且住，莫随芳草遽天涯。"]},{"t":"山中 其一","f":"七言律诗","c":["莫怪山翁老更迂，竹庵终日一团蒲。","万言万当不如默，百技百穷同是愚。","往事自惊天大胆，近诗空撚雪成须。","未忧卒岁无衣褐，紫凤天吴拆海图。"]},{"t":"山中 其六","f":"七言律诗","c":["黄纸红旗总不宜，绿蓑青笠久相知。","躬耕莘野一犁雨，亲见豳风七月诗。","老已自催蚕作茧，死时须用豹留皮。","山深未省人间世，黑白纵横几局棋。"]},{"t":"山中 其一","f":"七言律诗","c":["缭碧萦青一径深，倦随扶老上遥岑。","耕云自识本来面，曝日谁知见在心。","浮世事如风雨过，贵人头亦雪霜侵。","草庵虽窄乾坤阔，野鹤孤云不可寻。"]},{"t":"山中 其三","f":"七言律诗","c":["老去筋骸转觉衰，閒忙犹复费支持。","傍山新接龟头屋，为菊重编麂眼篱。","仕宦已忘如隔世，力田断不似逢时。","北窗高卧美无价，山鸟竟知吾是谁。"]},{"t":"山中用放翁韵 其一","f":"七言律诗","c":["一盂之饭一盘蔬，底用横身犯毁誉。","与世无缘空落落，登山有道但徐徐。","体中不快惟读易，老去更贫常典书。","四海谁知今夜月，梅花飘雪缟吾庐。"]},{"t":"山中用放翁韵 其二","f":"七言律诗","c":["山畦夜雨入春蔬，此手犹存足自誉。","甚爱踏青人已至，未能浮白子姑徐。","有山拄颊宁须笏，无策资身不为书。","莫向夕阳多感慨，百年长短一蘧庐。"]},{"t":"山行 其二","f":"七言律诗","c":["诗卷空留紫翠间，风花飞絮岂堪攀。","埋云已笑梦中梦，敲月更烦山上山。","长短百年谁是主，死生一概匹如閒。","病馀勘破人间事，底用瞿昙说八还。"]},{"t":"山行 其六","f":"七言律诗","c":["不肯诸贤季孟间，归来云月尽跻攀。","谁憎命达昔工部，未必诗穷今巨山。","两鬓雪霜多是病，一蓑烟雨可曾閒。","花前得酒微成醉，欢颊春红觉顿还。"]},{"t":"山行 其五","f":"七言律诗","c":["人情何翅抵黄间，鴥彼鸿冥杳莫攀。","宠辱可惊浮世事，是非不到好溪山。","怒鹏已较三千里，老马宁思十二閒。","丘壑傥容诗入社，肯将宗派继还还。"]},{"t":"山行 其三","f":"七言律诗","c":["老子浮沉田里间，犊车辕许野人攀。","饮中仙去东西玉，行处人传大小山。","天且莫教三月尽，我今无负一生閒。","春寒正惬牛衣暖，富贵从渠昼锦还。"]},{"t":"山行 其二","f":"七言律诗","c":["亦笑先生蔬一槃，云沈作坞卧荒寒。","童颜并已无班白，槁面旧曾如渥丹。","底用鱼烹双素尺，共知鹤化一黄冠。","芙蓉冷落秋萧索，只有篱花耐久看。"]},{"t":"山行 其一","f":"七言律诗","c":["高卧只消云半间，随缘栽果与猿攀。","不将此手遮西日，安用吾文移北山。","双燕来时春晻霭，一牛耕处月宽闲。","溪居已息机心久，莫遣惊鸥去不还。"]},{"t":"山行 其七","f":"七言律诗","c":["住世间须出世间，世情何事苦牵攀。","蟠胸自作三分国，觌面相悬两戒山。","大好闭门赢得睡，不多识字煞妨閒。","长须赤脚顽于我，未必淳风不再还。"]},{"t":"山行 其三","f":"七言律诗","c":["寒食清明数日间，青青杨柳与谁攀。","乾坤不尽云边眼，冰雪相堪屋上山。","时序只将诗拨遣，穷愁聊以酒防閒。","无心自是长生药，莫误丹炉觅大还。"]},{"t":"山行 其四","f":"七言律诗","c":["声名空自落人间，要是龙鳞不可攀。","春水白鸥多载酒，夕阳黄犊饱看山。","老吾于传懒成癖，之子有诗忙是閒。","四海流传如见问，为言飞鸟倦知还。"]},{"t":"山行 其二","f":"七言律诗","c":["亦笑吾身立两间，古人辙迹渺难攀。","斯文在昔豹窥管，吾力不量虻负山。","有识共知方寸好，无求方得几多閒。","一春大欠渠诗在，准拟晴时到处还。"]},{"t":"山行 其一","f":"七言律诗","c":["亦爱卢仝屋数间，野猿皋鹤共跻攀。","才登楼见一溪月，不出门行十里山。","有兴自携残藁醉，无人得似老夫閒。","樵青莫掩柴扉路，留与春风作往还。"]},{"t":"山行","f":"七言律诗","c":["野鹤相将拄杖前，倚松穿竹各欣然。","山行一匝又一日，云作四邻今四年。","名教之中元有地，吾心以外别无天。","平生老仆犹疑我，不是凡夫不是仙。"]},{"t":"山行 其一","f":"七言律诗","c":["岁晚谁同涧谷槃，一牛呼犊野烟寒。","村如有雪荞花白，山未著霜桐叶丹。","是处丰登茅店酒，老夫閒散竹皮冠。","醉归更草郊居赋，传与诗人作画看。"]},{"t":"山行漫兴","f":"七言律诗","c":["野性惟便水竹居，老来自觉转迂疏。","图书四壁饭不足，烟雨一犁春有馀。","纸上古人俱已矣，山中今我定何如。","春风独立鸟声碎，不是言诗亦起予。"]},{"t":"山间逢梅","f":"七言律诗","c":["自脱羸骖野水滨，隔桥孤倚欲迎人。","经年不睹雪霜面，一夜顿回天地春。","姑射仙犹疑昨梦，首阳人恐是前身。","岁寒莫问香何晚，毕竟凡花落后尘。"]},{"t":"山居","f":"七言律诗","c":["春溪甘滑漱山瓢，归卧藤阴藓径遥。","云气酿成巫峡雨，松声寒似浙江潮。","书生与世例迂阔，山意向人殊寂寥。","却喜庾郎贫到骨，韭畦时一摘烟苗。"]},{"t":"山居十首 其十","f":"五言律诗","c":["我爱山居好，畦蔬手自耘。","鸟声穿户过，鹤唳隔村闻。","石溜浑如雨，溪船尽是云。","烦君谢逋客，不用北山文。"]},{"t":"山居十首 其九","f":"五言律诗","c":["我爱山居好，遥岑碧四围。","云沈平钓石，草蔓亚樵扉。","野水喧姑恶，春阴怨姊归。","坐来还失笑，吾道是耶非。"]},{"t":"山居十首 其八","f":"五言律诗","c":["我爱山居好，新篁绿上竿。","草蕃侵路狭，地阔占云宽。","山响棋声湿，堂深树影寒。","柴门底须掩，非意不相干。"]},{"t":"山居十首 其七","f":"五言律诗","c":["我爱山居好，乾坤自一丘。","牡丹新富贵，杨柳旧风流。","妇喜醅新熟，儿誇麦有秋。","人生行乐耳，身外更何求。"]},{"t":"山居十首 其六","f":"五言律诗","c":["我爱山居好，跻攀缭暝烟。","偃松低可坐，横石劣容眠。","菊径重阳酒，梅花雪后天。","一筇吾事足，与世自无缘。"]},{"t":"山居十首 其四","f":"五言律诗","c":["我爱山居好，林霏晓未开。","龙蛇松薜荔，虎兕石莓苔。","太古云犹在，常时雨亦来。","暝岩眠处冷，不记到蓬莱。"]},{"t":"山居十首 其三","f":"五言律诗","c":["我爱山居好，閒吟树倚身。","田园无事日，天地自由人。","野竹穷三径，山苗草八珍。","醉归浑不记，黄犊自知津。"]},{"t":"山居十首 其二","f":"五言律诗","c":["我爱山居好，红稠处处花。","云粘居士屩，藤覆野人家。","入馔春烧笋，分灯夜作茶。","无人共襟抱，烟雨话桑麻。"]},{"t":"山居十首 其一","f":"五言律诗","c":["我爱山居好，林梢一片晴。","野烟禽谇语，春水柳閒情。","藓石随行枕，藤花醒酒羹。","吾诗不堪煮，亦足了吾生。"]},{"t":"山居十首 其五","f":"五言律诗","c":["我爱山居好，堆豗忽坐忘。","草塘银泼剌，庵户铁琅珰。","只道云藏坞，那知市隔墙。","人嫌吾寂寞，吾亦笑人忙。"]},{"t":"山墅 其三","f":"五言律诗","c":["且莫嫌穷僻，山居尽自奇。","候樵分玉蕈，熏穴得香狸。","杯隽明冰片，崖寒孕雪芝。","不遗吾一美，惭尔野人为。"]},{"t":"山墅 其二","f":"五言律诗","c":["山冱雪云低，荒芜略有蹊。","逢人多说虎，隔坞忽闻鸡。","寒剖蜂房户，晴分麦町畦。","迩来神亦健，薄饭厌羹藜。"]},{"t":"山墅 其四","f":"五言律诗","c":["近况居然野，称呼只墅民。","有诗供课最，无债恼比邻。","性亦无嫌懒，人多不解贫。","每过田父宿，吾自认吾真。"]},{"t":"不寐 其二","f":"五言律诗","c":["不寐何为者，閒人最号忙。","酿方传得法，诗未足成章。","药草霜多损，寒蔬雨半荒。","幸无天下责，夔卨在岩廊。"]},{"t":"中秋","f":"七言律诗","c":["晓入云堂已起单，病留法喜太无端。","当涂月拟中秋见，建邺水仍江上寒。","与世不供三笑别，暮年转觉四并难。","鸬鹚杓有铜花绿，最负今宵白玉盘。"]},{"t":"乌衣园","f":"七言律诗","c":["吴宫晋苑半桑麻，路入长干野草花。","秋晚夕阳空巷陌，蓄时燕子几人家。","不携妓与东山醉，曾赌棋输别墅哗。","已近重阳风雨少，菊花篱落酒旗斜。"]},{"t":"书戴式之诗卷","f":"七言律诗","c":["七十行年戴石屏，同时诸老各凋零。","扁舟归去自渔舍，冷骨秋来更鹤形。","天地无情头尽白，江山有分眼终青。","剡溪定有人乘兴，月下柴门不用扃。"]},{"t":"五月初四大水","f":"五言律诗","c":["山云一夜雨，溪涨疾于飞。","小市通为壑，幽居半及扉。","木披龙有迹，墙断鹤无归。","书帙方狼籍，谁看旧钓矶。"]},{"t":"以梅送王尉 其二","f":"七言律诗","c":["才有骚情例合癯，只销清供老伊蒲。","孔方兄自非吾党，木上座堪寻酒徒。","寄子梅花逢驿使，败人诗兴苦催逋。","夜寒梦到西窗竹，明月一床冰一壶。"]},{"t":"以梅送王尉 其一","f":"七言律诗","c":["雪涧偶逢山泽癯，相携茅屋对团蒲。","古心不为世情改，老气了非流俗徒。","三读离骚多楚怨，一生知己只林逋。","诗成不值渠为伴，持醉主人双玉壶。"]},{"t":"元夕","f":"七言律诗","c":["茅屋相看冷似冰，蒲团孤坐澹于僧。","数行老墨閒居赋，一炷寒灯耐久朋。","时异不供三太息，吾衰何啻百无能。","后山亦有梅花月，不复年时兴可乘。"]},{"t":"元夕雪用韵","f":"七言律诗","c":["山蹊一色轻明玉，遮尽青青印屐苔。","元夕不知今日是，春愁政用此时来。","年华鼎鼎双蓬鬓，身世悠悠一酒杯。","好事断无人问字，竹门隔坞不须开。"]},{"t":"元日","f":"七言律诗","c":["坎止流行一任他，年华其奈老夫何。","贫知醉有回天日，早得閒为却日戈。","野烧青归烟髣髴，溪痕晴涨雪坡陀。","屠苏只对梅花饮，茅屋竹篱春意多。"]},{"t":"元日","f":"七言律诗","c":["钓寂耕閒老病身，何堪附翼与攀鳞。","山中是处有诗思，天上自来无故人。","岁事共知双鬓雪，梅花又过一年春。","晴妍已有溪村兴，牛下柴车或可巾。"]},{"t":"元日雨 其一","f":"七言律诗","c":["那得工夫作往还，一犁取日破荒湾。","春今又绿山中草，酒不能朱镜里颜。","六十只馀三岁在，百年亦是霎时间。","村村雨色冥濛外，已觉天公露一斑。"]},{"t":"元日雨 其二","f":"七言律诗","c":["云泥隔断拜年人，天自怜予老病身。","荠菜共挑元日雨，梅花未放去年春。","风烟不尽惟吾老，造化无他只此仁。","小试园林栽接手，山中亦是一洪钧。"]},{"t":"内翰程端明挽诗 其二","f":"七言律诗","c":["旋踵之间政事堂，挂冠神武一何忙。","松风醉卧山前后，梅障留题春在亡。","八十磻溪才事业，百年落水自平章。","老天肯使斯文坠，剑履已空笙鹤翔。"]},{"t":"内翰程端明挽诗 其一","f":"七言律诗","c":["倒泻银河洗肺肝，初传冰句落人间。","吾州谁继龙溪老，内相宁论豹尾斑。","汲冢以来书尽读，商盘而上笔追还。","岂无名字藏金匮，只与君王丐一閒。"]},{"t":"凤凰台","f":"七言律诗","c":["白发久孤鹦鹉杯，碧梧自老凤凰台。","管夷吾亦仅知许，李谪仙今安在哉。","城郭是非秋雨外，江山形胜暮潮来。","小留只等中秋月，且放青冥万里开。"]},{"t":"劝耕 其一","f":"七言律诗","c":["郡如斗大亦何堪，耕雨锄烟亦饱谙。","共话桑麻真有味，久抛蓑笠得无惭。","野田春水自深浅，晴日鸟声时两三。","安得一牛横短笛，南山之北北山南。"]},{"t":"天基锡宴致语口号","f":"七言律诗","c":["春绿晴融太液池，好风都在万年枝。","宫墙璆玉韶音远，合殿珠环晓漏迟。","天近六龙扶翠辇，云深五凤挟瑶池。","镐京长启需云宴，先奏端平第一诗。"]},{"t":"太庙斋宿","f":"七言律诗","c":["正尔梅蒸苦翳霾，翛然清庙得心斋。","云连魏阙天尤近，树暗吴山雨亦佳。","黄道正中垂日月，赤囊犹遽接江淮。","思皇列考神灵在，傥许孤臣借玉阶。"]},{"t":"月岩","f":"七言律诗","c":["怪石堆云矗大空，女娲鍊出广寒宫。","一轮常满阴晴见，万古无亏昼夜同。","捣药声繁驱白兔，漏天孔正透清风。","光明自照如来境，肯学姮娥西复东。"]},{"t":"木犀 其一","f":"七言律诗","c":["香到人间香更幽，月明风露正飕飕。","天开金粟如来藏，人立广寒宫殿秋。","几许多清冰脑片，一些来大雪花头。","此生若并凡红紫，安得奇芬死不休。"]},{"t":"木犀 其三","f":"七言律诗","c":["羽觞和月嚼冰黄，自笑诗肠老更刚。","四出雪花些小大，五千书传一齐香。","君从底处移仙籍，日饮无何作醉乡。","风露清寒付谁可，携归天禄校偏旁。"]},{"t":"木犀 其二","f":"七言律诗","c":["叶叶寒清粟粟黄，何年月斧落吴刚。","秋风误到人间世，幽壑难藏天上香。","渺立尘氛群玉府，独餐沆瀣碧云乡。","生来不并凡红紫，合在蟾蜍砚滴旁。"]},{"t":"水月园送王侍郎","f":"七言律诗","c":["送别孤山步绕湖，阑干尽处倚菰蒲。","翁之乐者山林也，客亦知夫水月乎。","万事不如归自好，百年聊与醉为徒。","藕花初醒莼丝老，唤住罾船鲙腹腴。"]},{"t":"牛庵后古松五株","f":"七言律诗","c":["山中老子一间屋，屋后秦人五大夫。","丘壑得专閒日月，衣冠甚伟古眉须。","计今当是百年物，著我添成六老图。","已有茯苓巢可俯，待烹石鼎疗诗癯。"]},{"t":"牛庵睡起","f":"词","c":["自束生刍起饭牛，隔林扣角更深幽。","半分不得诗书力，一饭常存?亩忧。","老去有肠堪贮酒，生来无骨可封侯。","开荒厓下田无几，种秫宁须与妇谋。"]},{"t":"王母望阙致语口号","f":"七言律诗","c":["晓跸初催上寿班，东风连夜致人间。","九重春醉金鸾殿，万岁声幽碧玉环。","大地山河年谷熟，太平日月羽书闲。","明朝第一番花吉，并与琼幡下虎关。"]},{"t":"风作","f":"七言律诗","c":["年光何啻蛇赴壑，仕宦略如鱼上竿。","畴昔本无温饱志，归来只作等閒看。","人间万事风涛急，雨外一蓑天地宽。","潮落海门烟树绿，举头已不见长安。"]},{"t":"兰溪晚泊","f":"五言律诗","c":["岸岸芦花白，空江多月明。","一帘秋色老，千里暮云平。","寒入霜前韭，香传雨后橙。","烦诗题品看，此酒旧知名。"]},{"t":"出关","f":"五言律诗","c":["江雨正冥冥，江鸥聚晚汀。","云深城阙丽，潮落海门青。","宇宙双蓬鬓，江湖几驿亭。","不须关卒逻，吾亦厌铜腥。"]},{"t":"古岩","f":"七言律诗","c":["廿年前此借僧单，留得松声入梦寒。","岁月可惊吾辈老，风烟仍作故人看。","山泉与佛结茶供，石屋无人蚀藓瘢。","亭角雨晴秋更碧，断云片片泊栏干。"]},{"t":"叶秘书致白龙涎","f":"七言律诗","c":["闭门老去著幽禅，趺坐时参柏子烟。","书册懒随黄犊角，岩霏宁识白龙涎。","蓬莱山复在何处，杞菊赋今谁与传。","不道宝书天尺五，肯分风月到林泉。"]},{"t":"四用韵答才老","f":"七言律诗","c":["江山带郭数家村，穷僻谁敲月下门。","谢绝往来缘事尽，争论胜负为棋喧。","爱閒宁有万金产，投老当誇两足尊。","不惜梅花三寸雪，并令回施给孤园。"]},{"t":"归来馆成再用韵","f":"七言律诗","c":["后门穿过荷葭坞，春草池塘一径苔。","尽废秫田妨醉去，旋苫山馆号归来。","知无骨相取金印，莫与春秋著玉杯。","自有梅花可人意，南枝开了北枝开。"]},{"t":"旧传有客谒一士夫题其刺云琴棋诗酒客因与谈笑戏成此诗","f":"七言律诗","c":["痴书到底成何事，只有穷愁上鬓丝。","铸错空糜六州铁，补鞋不似两钱锥。","谁欤莫逆溪山我，幸甚无能诗酒棋。","依旧挂书牛角去，笑渠到底是书痴。"]},{"t":"正月尽山间梅花犹有未放者","f":"七言律诗","c":["南枝寒尽著花迟，入我新年第一诗。","明月向人应有语，老天于物本无私。","自逋之后谁相得，未雪以前春不知。","尽让世间凡草木，再三守此岁寒姿。"]},{"t":"瓜洲晚渡","f":"七言律诗","c":["天地中间一叶舟，与鸥等是此生浮。","江淮千里水天碧，南北六朝烟树愁。","浪挟禹功吞巨海，寺骑娲石碍中流。","渔蓑不涉兴亡事，自醉自醒今白头。"]},{"t":"用赵尉韵寄题约山楼","f":"五言律诗","c":["可人期不至，楼外有佳山。","几点寒林画，一帘秋水环。","只烦诗五字，相与月三间。","贵贱交情薄，何妨自往还。"]},{"t":"用程兄韵奉诸公题跋还人","f":"七言律诗","c":["老砚生苔尔许时，谁怜官事落儿痴。","江湖十载春无据，天地一舟归有期。","客有相从蜗壳语，诗来云受鹤山知。","皮毛剥落惟真实，那用诸公绝妙辞。"]},{"t":"用韵简赵尉无牡丹","f":"七言律诗","c":["乱山深处有谁来，诗砚荒寒一寸埃。","特未可知天下事，断无相负掌中杯。","人传梅隐近入幕，我但糟丘高筑台。","竹友松朋真耐久，可曾将口问花魁。"]},{"t":"白鹭亭","f":"七言律诗","c":["荻花芦叶老风烟，独上秋城思渺然。","白鹭不知如许事，赤乌又复几何年。","六朝往事秦淮水，一笛晚风江浦船。","我辈人今竟谁是，只堪渔艇夕阳边。"]},{"t":"石孙受命","f":"七言律诗","c":["圣泽如春雨露宽，弃遗犹不绝衣冠。","万钉宝带翁无分，一幅花绫孙有官。","得免白丁何啻足，亲曾黄甲不堪看。","九经幸自澜翻熟，但守青灯雪屋寒。"]},{"t":"石孙试童子郡广文赠之诗代赓为谢 其二","f":"楚辞体","c":["命穷久已付之天，草木閒兮月一川。","无地可容携锸处，有孙犹在佩觿年。","老夫耄矣耕方熟，小子识之攻益坚。","万岁石场今尔耳，当家衣钵底须传。"]},{"t":"石孙试童子郡广文赠之诗代赓为谢 其一","f":"七言律诗","c":["不缘青紫不明经，科目多惭旧两生。","三豕鲁鱼曾未学，一蜗蛮触已争名。","栋梁材欲丘山重，沧海珠遗星斗明。","未必童乌能辨此，乃翁先已荷陶成。"]},{"t":"立春","f":"七言律诗","c":["诗傥穷人莫送穷，但穷诗亦不须工。","银幡雪柳人何似，翠缕琼丝菜则同。","百事到头惟早白，一年弹指又春红。","渔溪亦喜溪冰泮，新绿生肥撼钓筒。"]},{"t":"立春","f":"七言律诗","c":["花柳胚胎午夜风，一尊聊与破红封。","醉馀安用淄渑口，妙处元无泾渭胸。","纸帐不知寒浩荡，银幡自爱雪髼松。","小楼认得春来处，晴霭苍茫南北峰。"]},{"t":"立春前一日雪 其一","f":"七言律诗","c":["入冬妍暖几兼旬，明日银幡岁又新。","绝意六花无复腊，等閒一尺不胜春。","老天咳唾何难事，瘦地耕锄亦幸民。","径就梅梢嚼清冷，相如渴肺久生尘。"]},{"t":"立春前一日雪 其二","f":"七言律诗","c":["历眼看看剩浃旬，山河大地一齐新。","不成过腊都无雪，只隔明朝便是春。","夜半有谁过剡曲，年丰无处不尧民。","草亭只在梅花外，知与人间隔几尘。"]},{"t":"买菊栽","f":"七言律诗","c":["新绿丛丛手自培，东篱准拟白衣来。","荷锄政欠半畦雨，抱瓮空遗满径苔。","说与园丁重九近，毋烦老子再三催。","径须寻觅谁家有，带土移将一两栽。"]},{"t":"再用汪少卿韵","f":"五言律诗","c":["毕竟春晴好，杨花也送行。","驿程寒冉冉，江树晓晶晶。","水长船能驶，诗多担转轻。","江湖吾倦矣，茅屋几时成。"]},{"t":"再用韵","f":"七言律诗","c":["终须西塞老渔村，抵用南昌隐市门。","时序略如飞鸟过，世终何啻聚蚊喧。","竹其安否六太息，梅自癯然三可尊。","贫味却愁儿辈觉，未妨壁立病文园。"]},{"t":"吕宗卿以病谢客明日约饭则予行矣诗以代简","f":"七言律诗","c":["长松落落雪霜姿，欲往从之我所思。","剥啄始知摩诘病，推敲谁话贾僧诗。","可羞吾事蚊䖟等，坐失先生鸡黍期。","细雨断云秋晚路，此情犹有菊花知。"]},{"t":"有感","f":"七言律诗","c":["桃花红雨柳花绵，风物愁予重惘然。","满目江山分楚越，旧游池馆锁尘烟。","朝云漠漠今安在，夜月荒荒空自圆。","只有雪衣孤鹤在，竹间曾共耸吟肩。"]},{"t":"有蟹无酒","f":"七言律诗","c":["左手持螯欠酒杯，枉烹郭索亦冤哉。","老饕借尔为诗地，多病凭谁作睡媒。","归钓兴随春浩荡，独醒人与月徘徊。","渊明未必穷于我，薄有公田办秫材。"]},{"t":"次严陵","f":"五言律诗","c":["二月寒如此，杨花不受春。","路生寻店早，家近梦归频。","白鸟无尘事，青山自故人。","几时茅屋下，卜与尔为邻。"]},{"t":"次梁倅录囚上饶","f":"五言律诗","c":["此老清如许，宁求使节知。","檄分风宪重，山到月岩奇。","秋色深宜雨，寒花并入诗。","圣朝本仁厚，鼠辈亦吾儿。"]},{"t":"次韵陈料院 其三","f":"七言律诗","c":["书册元非幕府才，江山牵率老夫来。","略分秋色归吟卷，又误春蓑下钓台。","有意及时常轗轲，无心于物莫惊猜。","幽居亦有穷生活，麦陇蔬畦手自开。"]},{"t":"次韵三四弟","f":"七言律诗","c":["入手功名不厌迟，政须努力莫伤悲。","二难宁共姜肱被，一染谁怜墨子丝。","仕宦金吾吾亦爱，饥寒玉汝汝当知。","青灯夜寂聊参取，侑坐为铭只此诗。"]},{"t":"次韵乡友","f":"七言律诗","c":["书生作计已差殊，况复真穷五技鼯。","空费寸阴酬急羽，还同斗米饱侏儒。","鸥盟正尔隔千里，鹤梦何曾到九衢。","茅屋春寒明月夜，梅花曾与寄声无。"]},{"t":"次韵山居 其一","f":"七言律诗","c":["孤亭危受众峰朝，岁晚移床借避嚣。","梅次第花春漠漠，鹤相随睡夜寥寥。","诸公安用怒生瘿，老子岂为饥折腰。","更入乱云深处去，极知与世不同条。"]},{"t":"次韵山居 其三","f":"七言律诗","c":["文如翻海百川朝，不说从前两耳嚣。","径与此山俱寂寂，未应吾道竟寥寥。","一生不办雕龙口，十万谁缠骑鹤腰。","但得草茅休歇去，何如快活有新条。"]},{"t":"次韵山居 其四","f":"七言律诗","c":["閒民亦幸乐清朝，蓑笠过从语不嚣。","倏忽岂能知混沌，玄冥颇亦识参寥。","年华鼎鼎分杯面，筋力时时借树腰。","月冷霜寒惊鹤帐，住山活计太萧条。"]},{"t":"次韵才老","f":"七言律诗","c":["藏拙欲分萝月阴，十年回首愧重临。","吾徒空倚横天剑，此老长閒布地金。","案有法华山寂寂，门无俗客竹深深。","瘦藤莫厌频来往，同社壶觞手自斟。"]},{"t":"次韵方叔","f":"七言律诗","c":["江楼识面一跫然，语带烟霞似欲仙。","山雨竟寒清夜约，好风吹落碧云篇。","相逢客路思归日，几立梅花欲暮天。","有兴话诗吾傥住，一蓑须办雪溪船。"]},{"t":"次韵王兄","f":"七言律诗","c":["江分晓色洗征衣，吾道非邪傥是欤。","与世无缘伤骨鲠，归田有日放眉舒。","虎头食肉亦安用，牛背看山却自如。","留得荷锄双手在，尽堪老瓦一轩渠。"]},{"t":"次韵王尉天宁晚饭","f":"五言律诗","c":["借得山房住，清溪带晚林。","云应随鹤宿，诗亦对僧吟。","杯滑知能隽，窗深苦易阴。","剧知归思浩，吾亦识琴心。"]},{"t":"次韵王尉白事幕府","f":"七言律诗","c":["一痴便了公家事，尽可与诗宽作程。","书册不嫌官屋冷，香匜相对歙溪晴。","熟知白鹭难为伴，烦见青山且寄声。","此别不过旬日耳，又携孤啸上江城。"]},{"t":"次韵王尉贺雨","f":"七言律诗","c":["老天自不负吾君，谁向灵均三沐熏。","鹤立待收连夜雨，龙归看带入山云。","摩挲一饱岂易得，愁叹多年不忍闻。","亦欲买牛横短笛，华山一半倘容分。"]},{"t":"次韵王尉致香","f":"五言律诗","c":["客有知吾癖，能分一雪凉。","只将诗意思，自与梦商量。","竹密雨声隽，窗深山意长。","研朱对周易，老鼎亦英扬。"]},{"t":"次韵王尉赠别 其一","f":"七言律诗","c":["十载春泥溅客衣，江湖半已入吾诗。","事今岂得文章力，心亦难求世俗知。","山意向人如有语，鸥盟于我合归谁。","月明昨夜欺寒梦，未了西斋竹外棋。"]},{"t":"次韵王尉赠别 其二","f":"七言律诗","c":["摩挲老砚欲生衣，煞欠梅花别后诗。","明月夜怜无客共，故人心岂不吾知。","相看白眼了无忤，除却青山更有谁。","但得秫田供醉梦，世情付与烂柯棋。"]},{"t":"次韵卢监","f":"七言律诗","c":["兰亭人寂几何年，著我糟丘亦冗员。","寻访雪溪无酒债，主张禊帖有诗权。","千岩秀处书如堵，五月凉时藕似船。","只么拍浮真足矣，底须妄想到花边。"]},{"t":"次韵叶兄云崖","f":"七言律诗","c":["以酒为乡墨作庄，厓寒云亦为诗忙。","春山药草谁同斸，云径梅花只自香。","竹不碍山青入户，藓缘谢客绿侵床。","岂无枫叶吴江句，夜雨何时稻韭黄。"]},{"t":"次韵叶宗丞约游括苍","f":"七言律诗","c":["一诗不了苍州债，曾泊春沙问水程。","山自强如吾郡好，酒今闻有括滩清。","文章未得半分力，故旧难忘少日情。","已斸莓苔新种竹，恐无辞与此君盟。"]},{"t":"次韵田园居","f":"七言律诗","c":["带郭林塘尽可居，秫田虽少不如归。","荒烟五亩竹中半，明月一间山四围。","草卧夕阳牛犊健，菊留秋色蟹螯肥。","园翁溪友过从惯，怕有人来莫掩扉。"]},{"t":"次韵刘架阁和予壬寅入局诗","f":"七言律诗","c":["入开图籍底须钳，谁校蓬山三万签。","有竹两窗聊下榻，为梅一笑几巡檐。","虎头食肉亦安用，熊掌与鱼那得兼。","好事人来勤载酒，纵无奇字不渠厌。"]},{"t":"次韵刘簿祷雨西峰 其二","f":"七言律诗","c":["爱民端与共胞胎，消得黄金为筑台。","一道香烟随牒去，五更风雨入诗来。","雪灯字暗心犹在，霜叶衫枯首独回。","气格老苍能过我，柴门不厌为君开。"]},{"t":"次韵牟监簿斋宫","f":"七言律诗","c":["蛮触追奔竞一豪，市朝酣战万灵鼍。","斋房只在秋山外，吟卷自随明月多。","问字人须烦谢绝，敲门僧亦莫谁何。","竹宫曾见神君否，且乞天瓢为挽河。"]},{"t":"次韵红蕉","f":"七言律诗","c":["霜林蕉叶尚横陈，不易禁寒夜向晨。","以貌取人通体似，其心如我别般春。","两年开就花何晚，千里移将句有神。","待学伊蒲修净供，自烹菡萏当猩唇。"]},{"t":"次韵红蕉 其一","f":"七言律诗","c":["篱根宿草已陈陈，谁护蕉红到此晨。","雪里寸丹长似旧，人间万绿未知春。","翻经曾识观身法，乞种亲为土地神。","孤负晚风生酒兴，维摩示疾不沾唇。"]},{"t":"次韵红蕉 其二","f":"七言律诗","c":["山花山草杂前陈，谁解芬芳霰雪晨。","红菡萏肥如欲焰，绿玲珑卷过于春。","化工有意怜丘壑，老我无诗泣鬼神。","待唤曲生相暖熟，雨晴禽哢是歌唇。"]},{"t":"次韵行甫小集平山 其四","f":"七言律诗","c":["欲将春睡了春閒，谁遣杨花点暮颜。","世事不如眠白堕，人情何啻抵黄间。","茫无措手句中句，悔已噬脐山外山。","蚤晚定编长庆集，并教传写落乌蛮。"]},{"t":"次韵行甫小集平山 其一","f":"七言律诗","c":["不奈花时两手閒，共携诗砚对孱颜。","江南江北音书外，春去春来杨柳间。","骑鹤重寻烟雨句，征鸿欲没夕阳山。","百年风物一杯酒，叹息人间两触蛮。"]},{"t":"次韵行甫小集平山 其五","f":"七言律诗","c":["客愁聊以酒防闲，非复春风桃李颜。","北望未忘诸老在，中兴已是百年间。","非无烟雨无奇语，自有乾坤有此山。","杨柳岂知兴废事，夕阳依旧舞腰蛮。"]},{"t":"次韵行甫小集平山 其二","f":"七言律诗","c":["春风多可几曾閒，又为平山入醉颜。","流恨不穷江万里，与翁长在月三间。","半清半浊圣贤酒，似有似无烟雨山。","试问黄鹂相识否，绿阴深树自绵蛮。"]},{"t":"次韵县圃即事","f":"五言律诗","c":["凫鸭能閒暇，相依睡浅波。","海棠经雨过，杨柳受春多。","未必诗穷在，其如酒病何。","闭门春草长，吾亦断经过。"]},{"t":"次韵吴侍郎同集砚山","f":"七言律诗","c":["晚寒閒袖挥毫手，曲角栏干倚断云。","丘壑尽容诗独步，江淮相望月平分。","艰难鬓葆成霜茁，冷落梅花带雪芬。","酒不能平诗磊磈，杯行到手已醺醺。"]},{"t":"次韵吴枢密乌衣园旧韵","f":"七言律诗","c":["旧家门巷绿岧峣，尚忆狨鞯马意骄。","金凿落浮朱雀浦，玉丁东上紫宸朝。","燕随往事秋萧瑟，雁带夕阳江泬寥。","九日黄华晴亦好，底须风雨又潇潇。"]},{"t":"次韵吴殿撰多景楼见寄","f":"七言律诗","c":["多情王粲怕登楼，谁遣人间汗漫游。","莼菜梦回千里月，蘋花老却一江秋。","人如沙燕年年别，骚到湘累字字愁。","正尔相观衣带水，角声孤起暮云稠。"]},{"t":"次韵张录携书见过 其一","f":"七言律诗","c":["家在屏山东复东，高轩肯过白云中。","石桥自是神仙处，竹屋相传诗律工。","日暮春江愁李白，山寒秋菊老龟蒙。","时平莫袖挥毫手，此论于予却未公。"]},{"t":"次韵张录携书见过 其二","f":"七言律诗","c":["君家自有神奇在，底用浓熏到马班。","黄石一编灯火外，紫芒双剑斗牛间。","谁能莫府初开印，闻有诗人便入山。","雨过勘厅春草绿，与吾意思政相关。"]},{"t":"次韵李君携示唐告","f":"七言律诗","c":["唐家甲乙尊门族，谁有流传直到今。","一代衣冠王子表，三朝雨露圣人心。","曾经竹巷醉双玉，尽出花绫诺百金。","湖海半生今见子，摩挲未负老侵寻。"]},{"t":"次韵汪少卿祷雪有感","f":"七言律诗","c":["梅梢了未知寒在，剪取清溪作雪飞。","正草绿章笺玉帝，顿惊碧宙舞瑶妃。","卖刀我亦耕侯土，歌裤今谁典客衣。","想得夜窗春满袖，燕彝香煖醉吟归。"]},{"t":"次韵汪少卿赠别","f":"五言律诗","c":["一诗传戟外，春亦肯随行。","老不论圭瓒，寒于嚼水晶。","梦惊池草合，香泛墨花轻。","立尽沙头月，鸥清睡不成。"]},{"t":"次韵汪宰见寄 其二","f":"七言律诗","c":["半世青灯眼欲昏，谁知曾亦望中原。","雨荒塞草秋如洗，雪拥春蓑夜自温。","宠辱易生分别想，是非政可鹘崙吞。","不论茅屋锄犁外，但守平生六二坤。"]},{"t":"次韵汪宰见寄 其一","f":"七言律诗","c":["行行骢马劾粗豪，叱叱黄牛倦作劳。","穷则有馀名迹在，言之无作语声高。","谁求封禅家徒壁，自谓羲皇人似陶。","见说醉乡天地阔，此生聊向此中逃。"]},{"t":"次韵閒中","f":"七言律诗","c":["玲珑压辔系绒鞍，付与诗人洗眼看。","老子只凭双脚健，梅花相对一溪寒。","吾生焉往不三黜，此乐未央并四难。","并与竹间孤鹤语，倦飞底用插脩翰。"]},{"t":"次韵閒中","f":"七言律诗","c":["区中何日了尘缘，落草牛须蓦鼻穿。","乾没一生空岁月，见成三径老风烟。","山林有味从今我，钟鼎无心付老天。","田彼南山多种豆，不愁饥火苦相煎。"]},{"t":"次韵陈汤卿 其二","f":"五言律诗","c":["野径渔樵共，霜寒江上村。","乱山横紫翠，孤笛送黄昏。","满壁题诗暗，连墙贳酒浑。","往来今已熟，稚子又应门。"]},{"t":"次韵陈汤卿 其一","f":"五言律诗","c":["括苍烟雨顶，客木晚巑岏。","家远书难到，云深梦亦寒。","僧邀携茗试，客许借诗看。","琴冷梅花月，何时为一弹。"]},{"t":"次韵陈料院 其二","f":"七言律诗","c":["涉世曾经几折肱，径须归卧北村灯。","往来屑屑无家燕，去住匆匆旦过僧。","浦淑舟寒秋婉娩，江湖人老雪鬅鬙。","草堂便在山深处，无复莼鲈累季鹰。"]},{"t":"次韵陈料院 其四","f":"七言律诗","c":["久矣寒窗美曲肱，绝交书到短檠灯。","向来问舍渔樵侣，肯作归田粥饭僧。","耕罢夕阳牛觳觫，睡残明月鹤鬅鬙。","年来老懒略相似，见兔何能便放鹰。"]},{"t":"次韵陈料院 其一","f":"七言律诗","c":["红旗破贼本非才，白首为郎更此来。","群玉府应羞哙伍，碧油幢误筑燕台。","江行莫等蛟鼍怒，雨歇能令鸥鹭猜。","三径未荒归路好，秋风篱落菊花开。"]},{"t":"次韵陈祭酒直舍木犀","f":"七言律诗","c":["西雍夜直秋风底，断是龙涎不敢香。","月府肯分金粟粟，书床相对玉琅琅。","人间富贵梦不到，世外高寒味尽长。","亦笑柴桑千载士，同时祇识菊花黄。"]},{"t":"次韵净照","f":"七言律诗","c":["一筇一衲出山相，不道斯人故可人。","我已久闻挥翰手，师宁相对坐禅身。","山林有味青灯古，天地无情白发新。","认取本来真面目，瀑泉诗好未知津。"]},{"t":"次韵所居龙池巷","f":"七言律诗","c":["从来绝技似屠龙，莫倚神奇阿堵中。","但得直声如汲黯，尽渠曲学付孙洪。","草堂自作冥鸿计，药市宁收汗马功。","古井无波门巷静，再三不用起雷风。"]},{"t":"次韵林同年见寄","f":"七言律诗","c":["水驿山城几往来，雪鸥亦怪面生埃。","径归不为麒麟楦，多病竟孤鹦鹉杯。","老子地寒馀草径，广文官冷合兰台。","山居美不堪持赠，云湿堕樵羹芋魁。"]},{"t":"次韵罗制干投赠","f":"五言律诗","c":["中秋明日是，雨色半苍厓。","无月可吾子，有诗倾老怀。","人间棋局面，身外酒生涯。","莫及边头事，谁知浊与淮。"]},{"t":"次韵话别","f":"五言律诗","c":["一雨桐江滑，佳哉月一篷。","归犹惭怨鹤，悔不蚤冥鸿。","涉世书无用，寻山酒有功。","诸人如见问，贫耳却非穷。"]},{"t":"次韵郑司理时以掌故赘梱幕归未能也","f":"七言律诗","c":["二月江南柳正花，扶携贫病又天涯。","愁予夜雨莼鲈梦，老却春山笋蕨芽。","太白有芒兵未歇，杀青无补事堪嗟。","书生迂阔多如此，不为吟诗两鬓华。"]},{"t":"次韵郑佥判 其一","f":"七言律诗","c":["老我菟裘月一间，仰眠黄犊看青山。","有诗倚竹猿猱径，无梦排云虎豹关。","城郭是非溪隔断，风烟灭没笔追还。","底须一局销长日，并不能棋方是閒。"]},{"t":"次韵郑佥判 其六","f":"七言律诗","c":["白菰紫芰更红蕖，不枉平生水竹居。","醉眼岂知吾是我，机心亦笑子非鱼。","无能涉世何妨睡，有道登山只是徐。","六月好风清樾底，付渠天地一蘧蒢。"]},{"t":"次韵郑佥判 其八","f":"七言律诗","c":["诗穷不易办亭材，只恁荒寒处处苔。","种秫便当终老去，爱花能有几人来。","生前尽足竹三径，身外无穷水一杯。","未必诸贤知此意，柴门虽设不曾开。"]},{"t":"次韵郑佥判 其四","f":"七言律诗","c":["一枕羲皇失午熇，久知吾道定寥寥。","客来且拨浮蛆瓮，事过真成覆鹿蕉。","野性从来便水石，此生自合老渔樵。","移床更入深云处，厥木惟乔厥草夭。"]},{"t":"次韵郑佥判 其三","f":"七言律诗","c":["渔村留得旧蓑衣，鹭侣鸥朋共断矶。","衰发三千馀丈白，倦游五十二年非。","清风明月天四壁，老木苍藤草半扉。","寂寞相从交有道，骊驹未可遽言归。"]},{"t":"次韵郑佥判 其五","f":"七言律诗","c":["十亩山园赋遂初，左花右竹了无馀。","择阴老我自麋鹿，甘带何人不蝍蛆。","佛社独容陶令醉，帝城难作子公书。","行山且不携诗卷，只许鸱夷载后车。"]},{"t":"次韵郑佥判 其七","f":"七言律诗","c":["烟藤云木捲苍虬，更放琅玕出一头。","山下人家方酷暑，此中棋局自惊秋。","图书如昨不堪煮，风月无多谁与酬。","怪得纵横苏季子，岁寒也忆旧貂裘。"]},{"t":"次韵郑佥判 其二","f":"七言律诗","c":["不论山北与山南，是处移将竹两三。","亦爱村深工部屋，尚嫌门对相公潭。","夕阳归鸟占花坞，山雨饭牛规草庵。","口挂壁从生白醭，是中除酒百无堪。"]},{"t":"次韵郑总干 其三","f":"七言律诗","c":["过从一笑酒瓶空，不是樵翁即钓翁。","偶种竹成俱崛强，旋移花活尚神通。","前身已化归辽鹤，醉帖犹传戏海鸿。","新贵少年吾自老，世间白发几曾公。"]},{"t":"次韵郑总干 其二","f":"楚辞体","c":["我亦思兮天一涯，樊川诗老此曾家。","九夫容隔秋风浦，一独速眠春雨蛙。","竹屋有灯谁与共，秫田可酿不须赊。","何年又赋高轩过，豆粥犹能办咄嗟。"]},{"t":"次韵郑总干 其一","f":"七言律诗","c":["底须咄咄漫书空，未觉人间欠此翁。","黄犊自随谙寂寞，青山亦讳话穷通。","人方怒及水中蟹，我亦冥如天外鸿。","醉眼不知人几品，久将樵牧等三公。"]},{"t":"次韵郑总干 其四","f":"七言律诗","c":["蚁丘得丧事无涯，冷眼难瞒老作家。","公等功名千里马，山居鼓吹两池蛙。","牛羊野径通村近，虎豹天关去国赊。","本是秋风钓竿手，故吾犹在复何嗟。"]},{"t":"次韵郑省仓 其二","f":"七言律诗","c":["雨过苔矶片月新，黄琉璃簟岸纶巾。","平生不负杨临贺，半夜谁呼祈孔宾。","堪傲轩裳中酒圣，肯污笔砚论钱神。","北山猿鹤应惊怪，已觉尘埃不可亲。"]},{"t":"次韵郑省仓 其一","f":"七言律诗","c":["月满长汀晚沐新，一凉犹下耐冠巾。","江连碧树自今古，我与青山迭主宾。","乞巧未能从帝子，坐愚宁免辱溪神。","向来鸥鸟间何阔，莫是炎凉不我亲。"]},{"t":"次韵郑省仓见寄 其一","f":"七言律诗","c":["倦客京华鬓已疏，诗颠草圣了无馀。","别离菊酒才秋晚，流落椒盘忽岁除。","东阁士应羞哙伍，北山人有绝秦书。","草芦十具牛如办，却是求田胜本初。"]},{"t":"次韵郑省仓见寄 其二","f":"七言律诗","c":["老年梦不到歌姝，一笑离尊孰与娱。","岁事沈沈江上月，时情汎汎水中凫。","路贫如此谁来往，山意于人定有无。","牢落不堪持说似，诗成时一寄奚奴。"]},{"t":"次韵雨阻游人","f":"七言律诗","c":["村坞花飞片片红，横遭涩雨又悭风。","无何春事三分过，不肯游人一笑同。","穷胜园林惟我辈，傥来轩冕付诸公。","烟云两屐亦堪醉，莫问圣贤时一中。"]},{"t":"次韵秋夜","f":"七言律诗","c":["雨浥浮梁逗碧纱，短更催睡不停挝。","一声雁带塞愁过，八月槎随乡信赊。","别后故人频入梦，秋来燕子已还家。","相逢却喜诗无恙，醉墨淋漓黑老鸦。"]},{"t":"次韵秋崖落成","f":"七言律诗","c":["高亭著处出奇峰，不枉平生此兴浓。","力士铛随狂李白，华阳巾垫郭林宗。","菊花篱落秋寥廓，山市人家翠叠重。","病起不论双足茧，层巅更欲试诗筇。"]},{"t":"次韵胡兄 其二","f":"七言律诗","c":["猿惊鹤怨老江蓠，留得离骚到景差。","愚智共知穷有分，浮休俱与醉无涯。","人间狡兔自三窟，身外鹪鹩只一枝。","非意相干吾岂敢，年来端为冷齑吹。"]}]};